# --- core/messages.py ---

"""Application message templates with unmodified dynamic evidence parameters."""


class Message(str):
    """A canonical string that also retains the template needed for localization.

    Keeping a string subclass preserves JSON and existing finding comparisons.
    The explicit reduction retains metadata across dataclasses.asdict/deepcopy.
    """

    def __new__(cls, template: str, parameters: dict | None = None):
        parameters = dict(parameters or {})
        value = super().__new__(cls, template.format(**parameters) if parameters else template)
        value.template = template
        value.parameters = parameters
        return value

    def __reduce_ex__(self, protocol):
        return type(self), (self.template, self.parameters)


def msg(template: str, **parameters) -> Message:
    return Message(template, parameters)

# --- core/atomic.py ---

"""Publish complete local evidence without truncating an existing file."""
import os
import tempfile
from pathlib import Path


def publish_file(temporary: str | Path, target: str | Path, overwrite: bool = False) -> None:
    if overwrite:
        os.replace(temporary, target)
    elif os.name == 'nt':
        # Windows rename is an atomic move that refuses an existing target;
        # unlike hard links this also works on writable FAT/exFAT volumes.
        os.rename(temporary, target)
    else:
        # Atomic exclusive creation; a competing writer cannot be overwritten.
        os.link(temporary, target)
        os.unlink(temporary)


def atomic_write_text(path: str | Path, text: str, overwrite: bool = False) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix='.' + target.name + '.', suffix='.tmp', dir=target.parent)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8', newline='\n') as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        publish_file(temporary, target, overwrite)
    finally:
        Path(temporary).unlink(missing_ok=True)

