def query_winhttp_proxy() -> dict[str, Any]:
    """Read the default WinHTTP configuration, never a session or PAC result."""
    if os.name != 'nt':
        raise OSError('WinHTTP configuration requires Windows')
    from ctypes import wintypes
    class ProxyInfo(ctypes.Structure):
        _fields_ = [('access_type', wintypes.DWORD), ('proxy', ctypes.c_void_p), ('bypass', ctypes.c_void_p)]
    # Restrict this new API's DLL lookup to System32, including after UAC.
    api = ctypes.WinDLL('winhttp', use_last_error=True, winmode=0x800)
    kernel = ctypes.WinDLL('kernel32', use_last_error=True, winmode=0x800)
    api.WinHttpGetDefaultProxyConfiguration.argtypes = [ctypes.POINTER(ProxyInfo)]
    api.WinHttpGetDefaultProxyConfiguration.restype = wintypes.BOOL
    kernel.GlobalFree.argtypes = [ctypes.c_void_p]
    kernel.GlobalFree.restype = ctypes.c_void_p
    info = ProxyInfo()
    if not api.WinHttpGetDefaultProxyConfiguration(ctypes.byref(info)):
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        return {'ok': True, 'access_type': info.access_type,
                'proxy': ctypes.wstring_at(info.proxy) if info.proxy else '',
                'bypass': ctypes.wstring_at(info.bypass) if info.bypass else '',
                'scope': 'WinHTTP default configuration; sessions may override it'}
    finally:
        for pointer in (info.proxy, info.bypass):
            if pointer:
                kernel.GlobalFree(pointer)


def current_token_sid() -> str:
    """SID of the actual process token, used for backup directory ACLs."""
    from ctypes import wintypes
    advapi = ctypes.WinDLL('advapi32', use_last_error=True)
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    advapi.OpenProcessToken.argtypes = [wintypes.HANDLE, wintypes.DWORD, ctypes.POINTER(wintypes.HANDLE)]
    advapi.OpenProcessToken.restype = wintypes.BOOL
    advapi.GetTokenInformation.argtypes = [wintypes.HANDLE, ctypes.c_int, ctypes.c_void_p,
                                          wintypes.DWORD, ctypes.POINTER(wintypes.DWORD)]
    advapi.GetTokenInformation.restype = wintypes.BOOL
    advapi.ConvertSidToStringSidW.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    advapi.ConvertSidToStringSidW.restype = wintypes.BOOL
    kernel.GetCurrentProcess.argtypes = []
    kernel.GetCurrentProcess.restype = wintypes.HANDLE
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel.CloseHandle.restype = wintypes.BOOL
    kernel.LocalFree.argtypes = [ctypes.c_void_p]
    kernel.LocalFree.restype = ctypes.c_void_p
    token = wintypes.HANDLE()
    if not advapi.OpenProcessToken(kernel.GetCurrentProcess(), 0x0008, ctypes.byref(token)):
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        required = wintypes.DWORD()
        advapi.GetTokenInformation(token, 1, None, 0, ctypes.byref(required))
        if not required.value:
            raise ctypes.WinError(ctypes.get_last_error())
        data = ctypes.create_string_buffer(required.value)
        if not advapi.GetTokenInformation(token, 1, data, required, ctypes.byref(required)):
            raise ctypes.WinError(ctypes.get_last_error())
        # TOKEN_USER starts with SID_AND_ATTRIBUTES; its first member is PSID.
        sid = ctypes.cast(data, ctypes.POINTER(ctypes.c_void_p))[0]
        text_sid = ctypes.c_void_p()
        if not advapi.ConvertSidToStringSidW(sid, ctypes.byref(text_sid)):
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            return ctypes.wstring_at(text_sid)
        finally:
            kernel.LocalFree(text_sid)
    finally:
        kernel.CloseHandle(token)


def wininet_option_types() -> tuple[Any, Any]:
    from ctypes import wintypes
    class Value(ctypes.Union):
        # A void pointer preserves the allocated address for GlobalFree on query.
        _fields_ = [('dwValue', wintypes.DWORD), ('pszValue', ctypes.c_void_p), ('ftValue', wintypes.FILETIME)]
    class Option(ctypes.Structure):
        _fields_ = [('dwOption', wintypes.DWORD), ('Value', Value)]
    class Options(ctypes.Structure):
        _fields_ = [('dwSize', wintypes.DWORD), ('pszConnection', wintypes.LPWSTR),
                    ('dwOptionCount', wintypes.DWORD), ('dwOptionError', wintypes.DWORD),
                    ('pOptions', ctypes.POINTER(Option))]
    return Option, Options


def query_wininet_proxy() -> dict[str, Any]:
    """Read the LAN/default connection through the supported WinINET API only."""
    Option, Options = wininet_option_types()
    library = ctypes.WinDLL('wininet', use_last_error=True)
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    library.InternetQueryOptionW.argtypes = [ctypes.c_void_p, ctypes.c_ulong, ctypes.c_void_p,
                                            ctypes.POINTER(ctypes.c_ulong)]
    library.InternetQueryOptionW.restype = ctypes.c_int
    kernel.GlobalFree.argtypes = [ctypes.c_void_p]
    kernel.GlobalFree.restype = ctypes.c_void_p
    # Microsoft documents FLAGS_UI for reads on Windows 7+, FLAGS as fallback.
    for flag_option in (10, 1):
        array = (Option * 4)()
        for item, code in zip(array, (flag_option, 2, 3, 4)):
            item.dwOption = code
        options = Options(ctypes.sizeof(Options), None, 4, 0, array)
        size = ctypes.c_ulong(ctypes.sizeof(options))
        try:
            if not library.InternetQueryOptionW(None, 75, ctypes.byref(options), ctypes.byref(size)):
                if flag_option == 10:
                    continue
                raise ctypes.WinError(ctypes.get_last_error())
            return {'flags': int(array[0].Value.dwValue),
                    **{key: ctypes.wstring_at(item.Value.pszValue) if item.Value.pszValue else ''
                       for key, item in zip(('ProxyServer', 'ProxyOverride', 'AutoConfigURL'), array[1:])}}
        finally:
            # InternetQueryOption allocates each returned string; even failed
            # multi-option queries may have populated an earlier string.
            for pointer in {item.Value.pszValue for item in array[1:] if item.Value.pszValue}:
                kernel.GlobalFree(pointer)
    raise RuntimeError('WinINET query did not return connection options')


def proxy_policy_snapshot() -> dict[str, Any]:
    """Policies relevant to scope/configuration, including UI management locks."""
    names = ['ProxySettingsPerUser', 'Proxy', 'ProxyEnable', 'ProxyServer', 'ProxyOverride',
             'AutoConfigURL', 'AutoDetect']
    result = {}
    for label, hive in [('HKLM', winreg.HKEY_LOCAL_MACHINE), ('HKCU', winreg.HKEY_CURRENT_USER)]:
        for path, fields in [(POLICY_PATH, names),
                             (r'Software\Policies\Microsoft\Internet Explorer\Control Panel',
                              ['Proxy', 'Autoconfig', 'AutoConfig'])]:
            result[label + '\\' + path] = registry_values(hive, path, fields)
    return result


def is_admin() -> bool:
    try:
        return os.name == 'nt' and bool(ctypes.windll.shell32.IsUserAnAdmin())
    except (AttributeError, OSError):
        return False


def reg_get(root: Any, path: str, name: str) -> Any:
    if winreg is None:
        return None
    try:
        with winreg.OpenKey(root, path, 0, winreg.KEY_READ) as key:
            return winreg.QueryValueEx(key, name)[0]
    except OSError:
        return None


def registry_values(root: Any, path: str, names: list[str]) -> dict[str, Any]:
    result: dict[str, Any] = {'values': {}, 'types': {}, 'error': '', 'missing': False}
    if winreg is None:
        result['error'] = 'Windows registry unavailable'
        return result
    try:
        with winreg.OpenKey(root, path, 0, winreg.KEY_READ) as key:
            for name in names:
                try:
                    value, typ = winreg.QueryValueEx(key, name)
                    result['values'][name], result['types'][name] = value, typ
                except FileNotFoundError:
                    result['values'][name] = None
    except FileNotFoundError:
        result['missing'] = True
    except OSError as exc:
        result['error'] = f'{type(exc).__name__}: {exc}'
    return result

# --- core/keyfile.py ---

"""Windows key files with a protected user/SYSTEM DACL from creation.

Read security information and content from the same handle. Refuse insecure
existing files instead of silently changing the permissions of a user's file.
"""
import ctypes
import os
import secrets
from pathlib import Path
from ctypes import wintypes


def _key_apis():
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    security = ctypes.WinDLL('advapi32', use_last_error=True)
    kernel.CreateFileW.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD,
                                  ctypes.c_void_p, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    kernel.CreateFileW.restype = wintypes.HANDLE
    for name in ('ReadFile', 'WriteFile'):
        fn = getattr(kernel, name)
        fn.argtypes = [wintypes.HANDLE, ctypes.c_void_p, wintypes.DWORD,
                       ctypes.POINTER(wintypes.DWORD), ctypes.c_void_p]
        fn.restype = wintypes.BOOL
    kernel.FlushFileBuffers.argtypes = [wintypes.HANDLE]
    kernel.FlushFileBuffers.restype = wintypes.BOOL
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel.CloseHandle.restype = wintypes.BOOL
    kernel.LocalFree.argtypes = [ctypes.c_void_p]
    kernel.LocalFree.restype = ctypes.c_void_p
    security.ConvertStringSecurityDescriptorToSecurityDescriptorW.argtypes = [
        wintypes.LPCWSTR, wintypes.DWORD, ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p]
    security.ConvertStringSecurityDescriptorToSecurityDescriptorW.restype = wintypes.BOOL
    security.GetSecurityInfo.argtypes = [wintypes.HANDLE, ctypes.c_int, wintypes.DWORD,
        ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p),
        ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    security.GetSecurityInfo.restype = wintypes.DWORD
    security.GetSecurityDescriptorControl.argtypes = [ctypes.c_void_p,
        ctypes.POINTER(wintypes.WORD), ctypes.POINTER(wintypes.DWORD)]
    security.GetSecurityDescriptorControl.restype = wintypes.BOOL
    security.GetAce.argtypes = [ctypes.c_void_p, wintypes.DWORD, ctypes.POINTER(ctypes.c_void_p)]
    security.GetAce.restype = wintypes.BOOL
    security.ConvertSidToStringSidW.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p)]
    security.ConvertSidToStringSidW.restype = wintypes.BOOL
    return kernel, security


def _key_sid_text(kernel, security, sid):
    result = ctypes.c_void_p()
    if not security.ConvertSidToStringSidW(sid, ctypes.byref(result)):
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        return ctypes.wstring_at(result)
    finally:
        kernel.LocalFree(result)


def _check_key_acl(kernel, security, handle, user):
    owner, dacl, descriptor = ctypes.c_void_p(), ctypes.c_void_p(), ctypes.c_void_p()
    error = security.GetSecurityInfo(handle, 1, 0x5, ctypes.byref(owner), None,
                                    ctypes.byref(dacl), None, ctypes.byref(descriptor))
    if error:
        raise ctypes.WinError(error)
    try:
        control, revision = wintypes.WORD(), wintypes.DWORD()
        if not security.GetSecurityDescriptorControl(descriptor, ctypes.byref(control), ctypes.byref(revision)):
            raise ctypes.WinError(ctypes.get_last_error())
        if not dacl.value or not control.value & 0x1000 or _key_sid_text(kernel, security, owner) != user:
            raise PermissionError('Pseudonym key requires a protected user-owned DACL')
        # ACL header: revision BYTE, reserved BYTE, size WORD, ACE count WORD.
        count = ctypes.c_ushort.from_address(dacl.value + 4).value
        users = set()
        for index in range(count):
            ace = ctypes.c_void_p()
            if not security.GetAce(dacl, index, ctypes.byref(ace)):
                raise ctypes.WinError(ctypes.get_last_error())
            kind, flags = ctypes.string_at(ace, 2)
            if kind != 0 or flags != 0:  # Only explicit ACCESS_ALLOWED_ACE.
                raise PermissionError('Unexpected pseudonym key ACE')
            sid = _key_sid_text(kernel, security, ctypes.c_void_p(ace.value + 8))
            if sid not in (user, 'S-1-5-18'):
                raise PermissionError('Pseudonym key grants another principal access')
            users.add(sid)
        if user not in users:
            raise PermissionError('Pseudonym key has no user ACE')
    finally:
        kernel.LocalFree(descriptor)


def read_private_key(path: Path) -> str:
    kernel, security = _key_apis()
    # OPEN_REPARSE_POINT prevents following a substituted key symlink.
    # Permit other publishers to test an exclusive rename while this handle is
    # open. Content and ACL are still read from this handle, with writes denied.
    handle = kernel.CreateFileW(str(path), 0x80020000, 5, None, 3, 0x00200000, None)
    if handle == ctypes.c_void_p(-1).value:
        raise ctypes.WinError(ctypes.get_last_error())
    try:
        _check_key_acl(kernel, security, handle, current_token_sid())
        buffer, size = ctypes.create_string_buffer(128), wintypes.DWORD()
        if not kernel.ReadFile(handle, buffer, len(buffer), ctypes.byref(size), None):
            raise ctypes.WinError(ctypes.get_last_error())
        if size.value >= len(buffer):
            raise ValueError('Pseudonym key file is too large')
        return buffer.raw[:size.value].decode('ascii')
    finally:
        kernel.CloseHandle(handle)


def publish_private_key(path: Path, text: str) -> None:
    kernel, security = _key_apis()
    user = current_token_sid()
    descriptor = ctypes.c_void_p()
    sddl = f'O:{user}D:P(A;;FA;;;SY)(A;;FA;;;{user})'
    if not security.ConvertStringSecurityDescriptorToSecurityDescriptorW(sddl, 1, ctypes.byref(descriptor), None):
        raise ctypes.WinError(ctypes.get_last_error())
    class Attributes(ctypes.Structure):
        _fields_ = [('length', wintypes.DWORD), ('descriptor', ctypes.c_void_p), ('inherit', wintypes.BOOL)]
    attributes = Attributes(ctypes.sizeof(Attributes), descriptor, False)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name('.' + path.name + '.' + secrets.token_hex(16) + '.tmp')
    created = False
    try:
        handle = kernel.CreateFileW(str(temporary), 0x40020000, 0, ctypes.byref(attributes), 1, 0x80, None)
        if handle == ctypes.c_void_p(-1).value:
            raise ctypes.WinError(ctypes.get_last_error())
        created = True
        try:
            _check_key_acl(kernel, security, handle, user)
            data, size = text.encode('ascii'), wintypes.DWORD()
            if not kernel.WriteFile(handle, data, len(data), ctypes.byref(size), None) or size.value != len(data):
                raise ctypes.WinError(ctypes.get_last_error())
            if not kernel.FlushFileBuffers(handle):
                raise ctypes.WinError(ctypes.get_last_error())
        finally:
            kernel.CloseHandle(handle)
        # Same-volume Windows rename is exclusive; readers see only complete keys.
        os.rename(temporary, path)
    finally:
        kernel.LocalFree(descriptor)
        if created:
            temporary.unlink(missing_ok=True)

# --- core/privacy.py ---

"""One field-aware privacy policy for reports, snapshots and diff exports.

Stable opaque markers retain comparisons. Raw inventories are available only
through the caller's explicit full/private export option.

Opaque markers are HMAC-SHA256 pseudonyms under a random per-installation key.
An unkeyed hash of a private IPv4 address or a MAC address with a known vendor
prefix is reversible by enumeration in seconds and links every report that
contains the same value; a keyed pseudonym is neither, unless the key leaks.
"""
import hashlib
import hmac
import ipaddress
import json
import ntpath
import os
import platform
import re
import secrets
import threading
from pathlib import Path
from typing import Any


PRIVATE_FIELDS = frozenset({
    'sid', 'machine', 'device', 'username', 'computername', 'hostname',
    'token', 'api_key', 'apikey', 'access_token', 'authorization',
    'password', 'passwd', 'secret', 'ssid', 'profilename',
})
IDENTIFIER_FIELDS = frozenset({
    'interfaceguid', 'interfaceid', 'guid', 'pnpdeviceid', 'instanceid',
    'registrykey', 'macaddress', 'physicaladdress',
    'node_id', 'source_id', 'target_id', 'object_key', 'provider_key', 'callout_key', 'filter_key',
})
VERSION_FIELDS = frozenset({'version', 'displayversion', 'application_version', 'fileversion', 'productversion'})
PATH_FIELDS = frozenset({
    'path', 'pathname', 'installlocation', 'uninstallstring', 'quietuninstallstring',
    'pathtosignedproductexe', 'pathtosignedreportingexe', 'backup',
})
_OPAQUE = re.compile(r'^<(?:id|ip|mac)-[0-9a-f]+>$|^<private-value-redacted>$')
PSEUDONYM_SCHEME = 'hmac-sha256-v1'
_PSEUDONYM_LOCK = threading.Lock()
_PSEUDONYM_STATE: dict[str, Any] = {'key': None, 'source': ''}


def pseudonym_key_path() -> Path:
    """Per-user key location; the override exists so test runs never touch a profile."""
    override = os.environ.get('WINNETDIFF_PSEUDONYM_KEY_FILE')
    if override:
        return Path(override)
    return Path(os.environ.get('LOCALAPPDATA', str(Path.home() / '.config'))) / 'WinNetDiff' / 'pseudonym.key'


def _read_key(path: Path) -> bytes:
    text = (read_private_key(path) if os.name == 'nt' else path.read_text(encoding='ascii')).strip()
    if not re.fullmatch(r'[0-9a-f]{64}', text):
        raise ValueError('pseudonym key file is not 64 lowercase hex characters')
    return bytes.fromhex(text)


def _publish_install_key(path: Path, text: str) -> None:
    if os.name == 'nt':
        publish_private_key(path, text)
    else:
        atomic_write_text(path, text, overwrite=False)


def _load_install_key(path: Path) -> tuple[bytes, str]:
    """Read or atomically create the install key; never overwrite an existing file.

    An unreadable or malformed key is left untouched for the user to inspect and
    this process uses an ephemeral key. Snapshots record the key fingerprint, so
    files written under different keys refuse to compare instead of mismatching.
    """
    try:
        return _read_key(path), 'install'
    except FileNotFoundError:
        pass
    except (OSError, ValueError, UnicodeError):
        return secrets.token_bytes(32), 'ephemeral'
    key = secrets.token_bytes(32)
    try:
        # Exclusive publish: a concurrent first run cannot replace another key.
        _publish_install_key(path, key.hex() + '\n')
        return key, 'install'
    except OSError:
        # Windows can report ACCESS_DENIED/SHARING_VIOLATION, rather than
        # FILE_EXISTS, if another process is reading the winner during rename.
        # A valid protected key that appeared meanwhile is authoritative. Never
        # replace it; failed/unsafe reads still fall back to a session key.
        try:
            return _read_key(path), 'install'
        except (OSError, ValueError, UnicodeError):
            return secrets.token_bytes(32), 'ephemeral'


def set_pseudonym_key(key: bytes | None, source: str = 'explicit') -> None:
    """Install an explicit key, or None to reload lazily from the key file."""
    if key is not None and (not isinstance(key, bytes) or len(key) < 16):
        raise ValueError('pseudonym key must be at least 16 bytes')
    with _PSEUDONYM_LOCK:
        _PSEUDONYM_STATE.update(key=key, source=source if key is not None else '')


def pseudonym_key() -> bytes:
    with _PSEUDONYM_LOCK:
        if _PSEUDONYM_STATE['key'] is None:
            _PSEUDONYM_STATE['key'], _PSEUDONYM_STATE['source'] = _load_install_key(pseudonym_key_path())
        return _PSEUDONYM_STATE['key']


def pseudonym_key_source() -> str:
    pseudonym_key()
    return _PSEUDONYM_STATE['source']


def pseudonym_digest(purpose: str, data: str, length: int) -> str:
    message = ('winnetdiff/' + purpose + '/v1\0' + data).encode('utf-8', 'surrogatepass')
    return hmac.new(pseudonym_key(), message, hashlib.sha256).hexdigest()[:length]


def pseudonym_key_id() -> str:
    """Public fingerprint used only to detect files created under different keys."""
    return pseudonym_digest('key-id', '', 16)


def _opaque(value: Any, kind: str = 'id') -> Any:
    if value in (None, '') or isinstance(value, str) and _OPAQUE.fullmatch(value):
        return value
    # The kind is a display prefix only, as before: one value maps to one token.
    return '<' + kind + '-' + pseudonym_digest('opaque', str(value), 12) + '>'


# Only a small allowlist of file extensions is safe enough to retain in a
# public report. Directory names and ambiguous command paths stay concealed.
_SAFE_LEAF = re.compile(r'(?i)^[^\\/\s<>|,;"\']+\.(?:sys|exe|dll|inf|json|xml|log|py|txt|cat|ps1|cmd|bat|msi)$')


def _privacy_path(path: str, *, is_directory: bool = False) -> str:
    stripped = path.strip().strip('"')
    leaf = ntpath.basename(stripped.replace('/', '\\'))
    if not is_directory and _SAFE_LEAF.fullmatch(leaf):
        return '<local-path>/' + leaf
    return '<local-path>'


def _private_path(match: re.Match) -> str:
    return _privacy_path(match.group(0).rstrip('.,;:'))


def redact(value: str, *, mask_ips: bool = True) -> str:
    text = str(value)
    if text.lstrip().startswith(('{', '[')):
        try:
            structured = json.loads(text)
            if isinstance(structured, (dict, list)):
                return json.dumps(redacted_data(structured), ensure_ascii=False, indent=2)
        except (ValueError, RecursionError):
            pass
    # Error prefixes often precede an embedded JSON object. Keep its field
    # context too, including escaped quotes inside credentials and versions.
    decoder = json.JSONDecoder()
    fragments, end = [], 0
    for match in list(re.finditer(r'[\[{]', text))[:32]:
        if match.start() < end:
            continue
        try:
            structured, consumed = decoder.raw_decode(text[match.start():])
        except (ValueError, RecursionError):
            continue
        if isinstance(structured, (dict, list)):
            fragments.extend([redact(text[end:match.start()], mask_ips=mask_ips),
                              json.dumps(redacted_data(structured), ensure_ascii=False)])
            end = match.start() + consumed
    if fragments:
        fragments.append(redact(text[end:], mask_ips=mask_ips))
        return ''.join(fragments)
    text = re.sub(r'(?i)([a-z][a-z0-9+.-]*://)[^/@\s]+@', r'\1<credentials>@', text)
    text = re.sub(r'(?i)(?<![\w/])[^\s;=@:/]+:[^\s;@/]+@', '<credentials>@', text)
    # Cover colon, dash and route-print's six space-separated octets.
    text = re.sub(r'(?i)(?<![0-9a-f])(?:[0-9a-f]{2}[:-]){5}[0-9a-f]{2}(?![0-9a-f])',
                  lambda m: _opaque(m[0].replace('-', ':').lower(), 'mac'), text)
    text = re.sub(r'(?i)(?<![0-9a-f])(?:[0-9a-f]{2}[ \t]+){5}[0-9a-f]{2}(?![0-9a-f])',
                  lambda m: _opaque(':'.join(m[0].lower().split()), 'mac'), text)
    identities = [(os.environ.get('USERNAME', ''), '<user>'),
                  (os.environ.get('COMPUTERNAME', ''), '<computer>'), (platform.node(), '<computer>')]
    for identity, marker in identities:
        if identity and len(identity) >= 2 and not identity.isdecimal():
            # User/device identifiers also occur inside directory and adapter names.
            pattern = re.escape(identity)
            if identity.isascii():
                pattern = r'(?<![A-Za-z0-9])' + pattern + r'(?![A-Za-z0-9])'
            text = re.sub(pattern, lambda m: marker, text, flags=re.I)
    text = re.sub(r'(?i)([A-Z]:[\\/]+(?:Users|Documents and Settings)[\\/]+)[^\\/\r\n"\'<>]+', r'\1<user>', text)
    # Quoted paths may contain spaces; however an unquoted path MUST stop at
    # whitespace or an argument separator. Never stitch a prior directory
    # together with a later filename merely because it has a .sys/.exe suffix.
    text = re.sub(r'(?i)"[A-Z]:[\\/][^"\r\n]*"', _private_path, text)
    text = re.sub(r'''(?i)(?<![A-Za-z0-9+.-])[A-Z]:[\\/][^\s"\'<>|,;]+''', _private_path, text)

    text = re.sub(r'\\\\[^\\\s]+\\[^\r\n"\'<>|,;]+', _private_path, text)
    # An ambiguous *unquoted* path with an internal whitespace token and a
    # backslash cannot be split safely. Mask the remainder of that apparent
    # path rather than disclosing a second directory fragment.
    text = re.sub(r'(<local-path>)(?:[ \t]+[^\s=;<>"\']+[\\/][^\s=;<>"\']+)+',
                  r'\1', text)

    if mask_ips:
        def mask(match):
            try:
                return _opaque(str(ipaddress.ip_address(match[0])), 'ip')
            except ValueError:
                return match[0]
        text = re.sub(r'(?<![\w.])(?:\d{1,3}\.){3}\d{1,3}(?![\w.])', mask, text)
        text = re.sub(r'(?<![\w:])(?:[0-9A-Fa-f]{0,4}:){2,}[0-9A-Fa-f]{0,4}(?![\w:])', mask, text)
    text = re.sub(r'(https?://[^\s?#"\']+)[?#][^\s"\']*', r'\1?<query-redacted>', text)
    text = re.sub(r'(?i)(authorization\s*:\s*)(?:Bearer|Basic)\s+[^\r\n,;]+', r'\1<secret-redacted>', text)
    text = re.sub(r'''(?ix)(["']?(?:api[_-]?key|access[_-]?token|token|password|passwd|secret|authorization)["']?\s*[=:]\s*)(?:"(?:\\.|[^"\\\r\n])*"|'(?:\\.|[^'\\\r\n])*'|[^\s,;"'<>{}\[\]]+)''', r'\1<secret-redacted>', text)
    return text


def redacted_data(data: Any) -> Any:
    if isinstance(data, dict):
        result = {}
        for key, value in data.items():
            field = str(key).lower()
            if 'base64' in field or field in PRIVATE_FIELDS:
                result[key] = '<private-value-redacted>' if value not in (None, '') else value
            elif field == 'host' and 'scheme' in data and 'port' in data:
                # Enterprise proxy DNS names are local identities too. This
                # endpoint shape is separate from ordinary target-domain rows.
                result[key] = _opaque(value)
            elif field in ('proxy', 'bypass') and 'access_type' in data and isinstance(value, str):
                result[key] = _opaque(value)
            elif field in IDENTIFIER_FIELDS:
                result[key] = _opaque(value)
            elif field in VERSION_FIELDS and isinstance(value, str):
                result[key] = redact(value, mask_ips=False)
            elif field in PATH_FIELDS and isinstance(value, str) and re.search(r'(?i)([A-Z]:[\\/]|\\\\)', value):
                candidate = value.strip().strip('"')
                candidate = re.split(r'(?i)(?<=\.exe)\s|(?<=\.sys)\s|(?<=\.dll)\s', candidate, maxsplit=1)[0].strip('"')
                # InstallLocation is a directory even if its leaf resembles
                # a filename. Other fields retain only a known, whitespace-free
                # filename; never publish a private directory leaf.
                result[key] = _privacy_path(candidate, is_directory=(field == 'installlocation'))
            else:
                result[key] = redacted_data(value)
        return result
    if isinstance(data, (list, tuple)):
        return [redacted_data(value) for value in data]
    return redact(data) if isinstance(data, str) else data

