_SCENARIO_CN_TERMS = {
    "解除安裝": "卸载", "應用程式": "应用程序", "網路": "网络", "軟體": "软件",
    "位址": "地址", "資訊": "信息", "設定": "配置", "元件": "组件", "主機": "主机",
    "介面": "接口", "登錄": "注册表", "埠": "端口", "監聽": "监听", "伺服器": "服务器",
    "連線": "连接", "交握": "握手", "逾時": "超时", "預設": "默认", "憑證": "证书",
    "使用者": "用户", "發布者": "发布者", "原廠": "厂商", "唯讀": "只读", "檔案": "文件",
    "停用": "禁用", "資料": "数据", "程式": "程序", "可攜式": "便携式", "封包": "数据包",
    "目的": "目标", "回應": "响应", "通路": "路径", "核對": "核查", "網卡": "网卡",
    "啟用": "启用", "移除": "移除", "診斷": "诊断", "執行": "执行", "快取": "缓存",
}


def _scenario_simplified(text: str) -> str:
    for source, target in _SCENARIO_CN_TERMS.items():
        text = text.replace(source, target)
    extra = str.maketrans(dict(pair for pair in (
        "嘗尝 隨随 係系 連连 牆墙 復复 來来 憑凭 歸归 屬属 躍跃 綴缀 長长 個个 響响 舉举 針针 兩两 協协 網网 詢询 純纯 務务 視视 兒儿 遺遗 庫库 問问 題题 產产 適适 鎖锁 驅驱 達达 遲迟 內内 裝装 徑径 惡恶 筆笔 雖虽 經经 構构 進进 維维 編编 隱隐 掃扫 縮缩 釋释 採采 欄栏"
    ).split()))
    return text.translate(SIMPLIFIED_CHARACTERS).translate(extra)


SCENARIO_TRANSLATIONS = {source: {"en": source, "zh-TW": target, "zh-CN": _scenario_simplified(target)}
                         for source, target in _SCENARIO_TW.items()}

