def proxy_endpoints(value: str) -> list[tuple[str, int]]:
    endpoints = []
    for item in re.split(r'[;\s]+', str(value or '')):
        item = re.sub(r'^(?:http|https|socks|socks4|socks5)=', '', item, flags=re.I)
        if not item:
            continue
        if not re.match(r'^[a-z][a-z0-9+.-]*://', item, re.I):
            item = 'http://' + item
        try:
            parsed = urllib.parse.urlsplit(item)
            host, port = (parsed.hostname or '').lower(), parsed.port
            local = host in LOCAL_IPS
            try:
                local = local or ipaddress.ip_address(host).is_loopback
            except ValueError:
                pass
            if local and port and 1 <= port <= 65535:
                endpoints.append((host, port))
        except ValueError:
            continue
    return list(dict.fromkeys(endpoints))


def inspect_listener(host: str, port: int) -> dict[str, Any]:
    result: dict[str, Any] = {'host': host, 'port': port, 'accepts_tcp': False,
                              'pid': None, 'program': None, 'error': '', 'confirmed_dead': False}
    # A refusal on both checks is stronger than a timeout (firewall/overload unknown).
    errors = []
    for _ in range(2):
        try:
            with socket.create_connection((host, port), timeout=0.45):
                result['accepts_tcp'] = True
            break
        except OSError as exc:
            errors.append(exc)
    result['confirmed_dead'] = len(errors) == 2 and all(
        isinstance(e, ConnectionRefusedError) or getattr(e, 'winerror', None) == 10061
        for e in errors)
    result['error'] = '; '.join(f'{type(e).__name__}: {e}' for e in errors)
    # Get-NetTCPConnection State Listen avoids localized netstat state labels.
    rows, error = ps_json(
        f'ConvertTo-Json -InputObject @(Get-NetTCPConnection -State Listen -LocalPort {port} '
        '-ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,OwningProcess) -Compress', 6)
    acceptable = {'0.0.0.0', '::', host}
    if host == 'localhost':
        acceptable |= {'127.0.0.1', '::1'}
    for row in rows:
        if row.get('LocalAddress') in acceptable:
            result['pid'] = row.get('OwningProcess')
            result['confirmed_dead'] = False
            break
    if result['pid'] is None:
        ns = run_command(['netstat', '-ano', '-p', 'tcp'], timeout=5)
        for line in ns['stdout'].splitlines():
            fields = line.split()
            if len(fields) < 5 or fields[0].upper() != 'TCP' or not fields[-1].isdigit():
                continue
            address, _, p = fields[1].rpartition(':')
            # Listen is identified by wildcard remote endpoint, independent of language.
            if p == str(port) and fields[2] in ('0.0.0.0:0', '[::]:0') and address.strip('[]') in acceptable:
                result['pid'] = int(fields[-1])
                result['confirmed_dead'] = False
                break
        if error:
            result['inventory_error'] = error
    if result['pid'] is not None:
        task = run_command(['tasklist', '/FI', f"PID eq {int(result['pid'])}", '/FO', 'CSV', '/NH'], 5)
        for row in csv.reader(io.StringIO(task['stdout'])):
            if len(row) > 1 and row[1].isdigit() and int(row[1]) == int(result['pid']):
                result['program'] = row[0]
                break
    return result


def collect_proxy(cancel: Optional[threading.Event] = None) -> dict[str, Any]:
    user = registry_values(winreg.HKEY_CURRENT_USER, INET_PATH, PROXY_KEYS)
    machine = registry_values(winreg.HKEY_LOCAL_MACHINE, INET_PATH, PROXY_KEYS)
    policy = registry_values(winreg.HKEY_LOCAL_MACHINE, POLICY_PATH, ['ProxySettingsPerUser', 'Proxy'])
    userpolicy = registry_values(winreg.HKEY_CURRENT_USER, POLICY_PATH, ['Proxy', 'ProxySettingsPerUser'])
    machine_mode = policy['values'].get('ProxySettingsPerUser') == 0
    effective = machine if machine_mode else user
    result: dict[str, Any] = {
        'wininet': effective['values'], 'wininet_user': user, 'wininet_machine': machine,
        'policy': policy, 'policy_user': userpolicy, 'effective_scope': 'HKLM' if machine_mode else 'HKCU',
        'errors': [f'{label}: {x["error"]}' for label, x in
                   [('HKCU', user), ('HKLM', machine), ('policy', policy), ('user policy', userpolicy)] if x['error']]}
    try:
        result['wininet_api'] = query_wininet_proxy()
    except (OSError, RuntimeError, AttributeError) as exc:
        result['wininet_api'] = {'error': f'{type(exc).__name__}: {exc}'}
        result['errors'].append('WinINET API: ' + result['wininet_api']['error'])
    result['applicable_policy'] = proxy_policy_snapshot()
    for label, item in result['applicable_policy'].items():
        if item.get('error'):
            result['errors'].append(label + ': ' + item['error'])
    wh = run_command(['netsh', 'winhttp', 'show', 'proxy'], 8)
    direct = bool(re.search(r'direct access|直接访问|直接存取|没有代理服务器|no proxy server', wh['stdout'], re.I))
    result['winhttp'] = {'raw': wh['stdout'], 'is_direct': direct if wh['ok'] else None,
                         'error': '' if wh['ok'] else wh['stderr'], 'ok': wh['ok'],
                         'command_evidence': wh}
    try:
        result['winhttp_config'] = query_winhttp_proxy()
    except (OSError, AttributeError) as exc:
        result['winhttp_config'] = {'ok': False, 'error': f'{type(exc).__name__}: {exc}'}
    if not wh['ok']:
        result['errors'].append('WinHTTP: ' + wh['stderr'])
    envpath = r'SYSTEM\CurrentControlSet\Control\Session Manager\Environment'
    for label, root, path in [('user', winreg.HKEY_CURRENT_USER, 'Environment'),
                               ('machine', winreg.HKEY_LOCAL_MACHINE, envpath)]:
        snap = registry_values(root, path, ENV_KEYS)
        result['environ_' + label] = snap['values']
        if snap['error']:
            result['errors'].append(f'Environment {label}: {snap["error"]}')
    result['environ_process'] = {k: os.environ.get(k) or os.environ.get(k.lower()) for k in ENV_KEYS}
    references: list[dict[str, Any]] = []
    for host, port in proxy_endpoints(effective['values'].get('ProxyServer') or ''):
        references.append({'host': host, 'port': port, 'source': 'WinINET',
                           'active': (effective['values'].get('ProxyEnable') == 1
                                      and bool(result['wininet_api'].get('flags', 0) & 2))})
    if wh['ok'] and not direct:
        pairs = re.findall(r'(127(?:\.\d{1,3}){3}|localhost|\[::1\]):(\d{1,5})', wh['stdout'], re.I)
        for host, port in pairs:
            if 0 < int(port) < 65536:
                references.append({'host': host.strip('[]').lower(), 'port': int(port),
                                   'source': 'WinHTTP', 'active': True})
    for scope in ('user', 'machine', 'process'):
        for key in ENV_KEYS[:3]:
            for host, port in proxy_endpoints(result['environ_' + scope].get(key) or ''):
                references.append({'host': host, 'port': port, 'source': f'env:{scope}:{key}',
                                   'active': 'application-dependent'})
    listeners = []
    for host, port in dict.fromkeys((r['host'], r['port']) for r in references):
        if cancel and cancel.is_set():
            result['errors'].append('cancelled: local proxy checks incomplete')
            break
        item = inspect_listener(host, port)
        item['references'] = [r for r in references if r['host'] == host and r['port'] == port]
        listeners.append(item)
    result['references'], result['local_listeners'] = references, listeners
    # PAC is recorded only, never downloaded/executed by this tool.
    result['pac_note'] = 'PAC/WPAD 實際行為由應用程式及每條連線設定決定；不下載或執行 PAC。'
    return result

# --- analysis/ownership.py ---

"""Vendor-independent, evidence-labelled host associations; never removal advice."""
import ntpath
import re
from typing import Any


def ownership_path(value: Any) -> str:
    text = str(value or '').strip().strip('"').replace('/', '\\')
    if not re.match(r'^[A-Za-z]:\\', text) or any(part == '..' for part in text.split('\\')):
        return ''
    return ntpath.normpath(text).casefold()


def _host_location(value: Any) -> str:
    path = ownership_path(value).rstrip('\\')
    # A root/shared container is not an application's ownership boundary.
    if not ntpath.splitdrive(path)[1].strip('\\') or ntpath.basename(path) in ('windows', 'system32', 'syswow64', 'drivers', 'program files', 'program files (x86)', 'programdata', 'users', 'common files'):
        return ''
    return path


def _owner_publisher(value: Any) -> str:
    text = str(value or '').strip().casefold()
    match = re.search(r'(?:^|,)\s*o\s*=\s*("[^"]+"|[^,]+)', text)
    return (match.group(1).strip('" ') if match else text).strip()


def associate_hosts(security: dict, routes: dict | None = None, wfp: dict | None = None) -> dict:
    """Keep exact links separate from possible publisher matches and unknowns.

    Missing uninstall registration alone is never generic orphan evidence.
    Imported WFP XML is historical configuration context, not a live filter test.
    """
    routes, wfp = routes or {}, wfp or {}
    completeness = security.get('completeness') or {}
    limits = {'apps': 2048, 'services': 4096, 'network_links': 4096, 'edges': 8192}
    apps = security.get('installed_apps') or []
    registry = security.get('service_registry') or []
    sources = ('services_wmi', 'drivers_wmi', 'driverquery')
    runtime = [(source, row) for source in sources if completeness.get(source) is True
               for row in security.get(source, [])]
    names = sorted({str(row.get('Name') or '').casefold() for _, row in runtime} |
                   {str(row.get('Name') or '').casefold() for row in registry})
    bounded = len(apps) <= limits['apps'] and len(names) <= limits['services']
    apps = apps[:limits['apps']]
    files = {ownership_path(row.get('Path')): row for row in security.get('files', [])}
    nodes, edges, components = [], [], []
    edge_truncated = [False]
    def edge(row):
        if len(edges) < limits['edges']: edges.append(row)
        else: edge_truncated[0] = True
    for index, app in enumerate(apps):
        nodes.append({'node_id': f'app:{index}', 'kind': 'installed_application',
                      'name': app.get('DisplayName'), 'path': app.get('InstallLocation')})
    links: dict[str, list[dict]] = {}
    legacy_names = {str(row.get('Name') or '').casefold() for row in security.get('evidence', [])}
    for binding in routes.get('bindings', []):
        owner = binding.get('OwnerEvidence') or {}
        services = [owner.get('Service')]
        co = owner.get('CoServices') or []
        services += [co] if isinstance(co, str) else co if isinstance(co, list) else []
        for name in services:
            if isinstance(name, str) and name.strip():
                links.setdefault(name.casefold(), []).append({'kind': 'ndis_service',
                    'component_id': binding.get('ComponentID'), 'enabled': binding.get('Enabled'),
                    'live': routes.get('query_status', {}).get('bindings') == 'ok'})
    providers: dict[str, list[dict]] = {}
    for row in wfp.get('ownership_records', []):
        if row.get('kind') == 'providers' and row.get('object_key') and row.get('service_name'):
            providers.setdefault(row['object_key'].casefold(), []).append(row)
    object_rows: dict[str, list] = {}
    for row in wfp.get('ownership_records', []):
        if row.get('object_key'):
            object_rows.setdefault(row['object_key'].casefold(), []).append(row)
    for key, objects in object_rows.items():
        if len(objects) != 1: continue
        row = objects[0]
        nodes.append({'node_id': 'wfp:' + key, 'kind': row.get('kind'), 'object_key': key})
        parent = row.get('callout_key') if row.get('kind') == 'filters' and row.get('callout_key') else row.get('provider_key')
        if parent and parent != key and len(object_rows.get(parent.casefold(), [])) == 1:
            edge({'source_id': 'wfp:' + key, 'target_id': 'wfp:' + parent.casefold(), 'relation': 'wfp_explicit_key_reference'})
    for key, records in providers.items():
        if len(records) != 1:
            continue  # Conflicting duplicate keys cannot establish a host.
        row = records[0]
        edge({'source_id':'wfp:' + key, 'target_id':'service:' + row['service_name'].casefold(), 'relation':'wfp_provider_service'})
        links.setdefault(row['service_name'].casefold(), []).append({
            'kind': 'wfp_provider_service', 'provider_key': key, 'live': False,
            'linked_objects': sum(item.get('provider_key', '').casefold() == key
                                  for item in wfp.get('ownership_records', []) if item.get('kind') != 'providers')})
    link_count = sum(map(len, links.values()))
    bounded = bounded and link_count <= limits['network_links'] and not wfp.get('ownership_truncated')
    for name in sorted((set(links) | legacy_names) - set(names))[:limits['services']]:
        nodes.append({'node_id': 'service:' + name, 'kind': 'service_or_driver', 'name': name, 'state': 'not_observed'})
        components.append({'Name':name, 'Status':'host_not_observed', 'Running':False,
            'Path':'', 'OwnerApps':[], 'PossibleHosts':[], 'NetworkLinks':links.get(name,[])[:32],
            'RuntimeSources':[], 'RegistrationPresent':False, 'Inconsistency':'',
            'File':{}, 'EligibleCorroboration':False})
    for name in names[:limits['services']]:
        if not name or name not in links and name not in legacy_names:
            continue
        peers = [(source, row) for source, row in runtime if str(row.get('Name') or '').casefold() == name]
        registered = [row for row in registry if str(row.get('Name') or '').casefold() == name]
        images = {ownership_path(normalize_binary_path(row.get('PathName', ''))) for _, row in peers} | {ownership_path(normalize_binary_path(row.get('PathName', ''))) for row in registered}
        images.discard('')
        image = next(iter(images)) if len(images) == 1 else ''
        # Alias registration at the exact same binary is explicit counterevidence.
        alias_registered = bool(image) and any(ownership_path(normalize_binary_path(row.get('PathName', ''))) == image for row in registry)
        metadata = files.get(image, {})
        running = any(row.get('Started') is True or str(row.get('State') or '').casefold() in
                      ('running', '运行中', '正在运行', '執行中') for _, row in peers)
        owners, possible = [], []
        for index, app in enumerate(apps):
            location = _host_location(app.get('InstallLocation'))
            if image and location and image.startswith(location + '\\'):
                owners.append(app.get('DisplayName') or f'app:{index}')
                edge({'source_id': 'service:' + name, 'target_id': f'app:{index}', 'relation': 'binary_within_install_location'})
            elif (metadata.get('SignatureStatus') == 'Valid' and metadata.get('Publisher')
                  and _owner_publisher(metadata['Publisher']) == _owner_publisher(app.get('Publisher'))):
                possible.append(app.get('DisplayName') or f'app:{index}')
                edge({'source_id': 'service:' + name, 'target_id': f'app:{index}', 'relation': 'possible_shared_signer_only'})
        network = links.get(name, [])[:32]
        concrete_network = any(link['kind'] == 'ndis_service' and link['live'] and link['enabled'] is True for link in network)
        complete_absence = bounded and completeness.get('installed_apps') is True and completeness.get('service_registry') is True
        inconsistency = ('registration_missing' if not registered and not alias_registered else
                         'running_binary_missing' if metadata.get('Exists') is False else '')
        status = ('owner_installed' if owners else 'owner_possible' if possible else
                  'inventory_incomplete' if not complete_absence else
                  'orphan_evidence' if running and concrete_network and inconsistency and bool(image) else 'owner_unknown')
        row = {'Name': next((str(p.get('Name')) for _, p in peers), name), 'Status': status,
               'Running': running, 'Path': image, 'OwnerApps': owners, 'PossibleHosts': possible,
               'NetworkLinks': network, 'RuntimeSources': sorted({source for source, _ in peers}),
               'RegistrationPresent': bool(registered or alias_registered), 'Inconsistency': inconsistency,
               'File': metadata, 'EligibleCorroboration': status == 'orphan_evidence'}
        if network or name in legacy_names: components.append(row)
        nodes.append({'node_id': 'service:' + name, 'kind': 'service_or_driver', 'name': row['Name'], 'path': image})
        for index, link in enumerate(network):
            target = f'network:{name}:{index}'
            nodes.append({'node_id': target, **link})
            edge({'source_id': target, 'target_id': 'service:' + name, 'relation': link['kind']})
    node_ids = {row['node_id'] for row in nodes}
    valid_edges = [row for row in edges if row['source_id'] in node_ids and row['target_id'] in node_ids]
    return {'schema_version': 1, 'nodes': nodes, 'edges': valid_edges, 'components': components,
            'bounded_complete': bounded and not edge_truncated[0] and len(valid_edges) == len(edges), 'limits': limits, 'wfp_scope': 'imported_snapshot' if wfp else 'not_supplied',
            'limitations': ['Exact service keys and binary paths describe association, not causation.',
                'Signed publisher-only matches remain possible shared hosts.',
                'Imported WFP state is historical and does not prove a currently active filter.']}


def ownership_findings(ownership: dict, existing: list | None = None) -> list[Finding]:
    known = {str(row.get('Name') or '').casefold() for row in existing or []}
    findings = []
    for row in ownership.get('components', []):
        if str(row['Name']).casefold() in known:
            continue
        status = row['Status']
        findings.append(Finding('可疑' if status == 'orphan_evidence' else '資訊', '安全/驅動',
            msg('Network component host association: {name}', name=row['Name']),
            __import__('json').dumps(row, ensure_ascii=False),
            msg('Host association is configuration evidence. Unknown or absent ownership does not prove a faulty driver.'),
            code='ownership.' + status, confidence='中', risk='read_only'))
    return findings

# --- probes/proxy_path.py ---

"""Explicit, credential-free HTTP CONNECT evidence, separate from direct probes."""
import dataclasses
import datetime as dt
import fnmatch
import ipaddress
import re
import socket
import ssl
import time
import urllib.parse
from typing import Any


def _proxy_target(target: str) -> str:
    hosts = parse_hosts(target)
    if len(hosts) != 1:
        raise ValueError('Proxy path target must be one domain')
    return hosts[0]


def proxy_bypass(host: str, rules: str, *, windows: bool = False, port: int = 443) -> bool:
    """Documented diagnostic matching, not a claim about every client library."""
    host = host.casefold().rstrip('.')
    for rule in re.split(r'[;,]', str(rules or '')):
        rule = rule.strip().casefold()
        if not rule: continue
        if rule == '*': return True
        if windows and rule == '<local>' and '.' not in host and ':' not in host: return True
        try:
            if '/' in rule and ipaddress.ip_address(host) in ipaddress.ip_network(rule, strict=False): return True
        except ValueError: pass
        if rule.count(':') == 1 and rule.rsplit(':', 1)[1].isdigit():
            rule, selected_port = rule.rsplit(':', 1)
            if int(selected_port) != port: continue
        if windows:
            if fnmatch.fnmatchcase(host, rule): return True
        elif host == rule.lstrip('.') or host.endswith('.' + rule.lstrip('.')):
            return True
    return False


def _proxy_endpoint(value: str) -> dict:
    """Drop credentials before returning any data; reject ambiguous URL syntax."""
    try:
        explicit = '://' in value
        url = urllib.parse.urlsplit(value if explicit else 'http://' + value)
        host, port = url.hostname, url.port
        if not host or any(c.isspace() or ord(c) < 32 for c in value) or url.path not in ('', '/') or url.query or url.fragment:
            return {'status': 'invalid_proxy_configuration'}
        credentials = url.username is not None or url.password is not None
        scheme = url.scheme.casefold()
        port = port or (80 if explicit and scheme == 'http' else 443 if explicit and scheme == 'https' else None)
        if not port or not 1 <= port <= 65535: return {'status': 'invalid_proxy_configuration'}
        status = ('credentials_not_sent' if credentials else 'unsupported_proxy_scheme' if scheme != 'http' else 'eligible')
        return {'status': status, 'scheme': scheme, 'host': host, 'port': port,
                'credentials_sent': False, 'credentials_configured': credentials}
    except (ValueError, TypeError):
        return {'status': 'invalid_proxy_configuration'}


def proxy_path_plan(proxy: dict, target: str) -> dict:
    target = _proxy_target(target)
    rows = []
    def add(source, value, bypass='', windows=False, active=True, automatic=False):
        if automatic:
            rows.append({'source': source, 'status': 'auto_proxy_unresolved', 'eligible': False})
        if not value: return
        candidates = []
        for token in re.split(r'[;\s]+', str(value)):
            if not token: continue
            if '=' in token and '://' not in token.split('=', 1)[0]:
                mapping, token = token.split('=', 1)
                if mapping.casefold() != 'https': continue
            candidates.append(token)
        for value in candidates[:8]:
            row = {'source': source, **_proxy_endpoint(value), 'target': target}
            if not active: row['status'] = 'stored_or_inactive'
            elif automatic: row['status'] = 'auto_proxy_unresolved'
            elif proxy_bypass(target, bypass, windows=windows): row['status'] = 'bypassed_for_target'
            row['eligible'] = row['status'] == 'eligible'
            rows.append(row)
        if len(candidates) > 8: rows.append({'source':source, 'status':'configuration_limit', 'eligible':False})
    manual = proxy.get('wininet', {})
    api = proxy.get('wininet_api', {})
    flags = api.get('flags', 0) if not api.get('error') else 0
    add('WinINET', manual.get('ProxyServer') or api.get('ProxyServer'), manual.get('ProxyOverride') or api.get('ProxyOverride') or '',
        windows=True, active=manual.get('ProxyEnable') == 1 and bool(flags & 2),
        automatic=bool(manual.get('AutoConfigURL') or api.get('AutoConfigURL') or flags & 12))
    winhttp = proxy.get('winhttp_config', {})
    if winhttp.get('ok'):
        add('WinHTTP-default', winhttp.get('proxy'), winhttp.get('bypass', ''), windows=True, active=winhttp.get('access_type') == 3)
    else:
        rows.append({'source':'WinHTTP-default','status':'configuration_unknown','eligible':False})
    for scope in ('process', 'user', 'machine'):
        environment = proxy.get('environ_' + scope, {})
        add('env:' + scope, environment.get('HTTPS_PROXY') or environment.get('ALL_PROXY'), environment.get('NO_PROXY', ''), active=scope == 'process')
    return {'target': target, 'paths': rows[:64], 'network_tested': False,
            'limitations': ['Direct socket results do not establish application proxy behaviour.',
                'PAC/WPAD is not downloaded or executed. WinHTTP sessions and applications may override defaults.',
                'NO_PROXY and bypass matching vary by application; these are diagnostic interpretations.',
                'Only explicit HTTP CONNECT is supported; no credentials or automatic authentication are sent.']}


class _ProxyPathStop(Exception): pass


def _proxy_tls_context():
    return ssl.create_default_context()


def probe_proxy_path(target: str, endpoint: dict, *, confirmed: bool = False, cancel=None,
                     phase_timeout: float = 3, overall_timeout: float = 12) -> dict:
    target = _proxy_target(target)
    result = {'target': target, 'proxy': {k:endpoint[k] for k in ('scheme','host','port') if k in endpoint},
        'status':'not_confirmed', 'credentials_sent':False, 'target_ip_observed':False,
        'observed_at':dt.datetime.now(dt.timezone.utc).isoformat(), 'timings_ms':{}, 'tls_verified':False,
        'budgets': {'phase_seconds': phase_timeout, 'overall_seconds': overall_timeout}}
    if not confirmed: return result
    # Re-validate structured callers too, so neither CRLF nor credentials enter argv/headers.
    host, port = endpoint.get('host'), endpoint.get('port')
    if endpoint.get('scheme') != 'http' or not isinstance(host,str) or any(c.isspace() or ord(c)<32 or c in '/@\\?#' for c in host) or not host or type(port) is not int or not 1 <= port <= 65535 or endpoint.get('credentials_configured'):
        result['status']='unsupported_or_invalid_proxy'; return result
    if not 0 < phase_timeout <= 10 or not 0 < overall_timeout <= 30:
        raise ValueError('Proxy probe timeout is outside the bounded budget')
    started=time.perf_counter(); deadline=started+overall_timeout
    phase, phase_end, raw, secure = 'dns', min(deadline,started+phase_timeout), None, None
    def budget():
        if cancel and cancel.is_set(): raise _ProxyPathStop('cancelled')
        now=time.perf_counter()
        if now >= deadline and deadline <= phase_end: raise _ProxyPathStop('overall_timeout')
        if now >= phase_end: raise _ProxyPathStop('proxy_' + phase + '_timeout')
        if now >= deadline: raise _ProxyPathStop('overall_timeout')
        return min(deadline,phase_end)-now
    def headers(connection):
        data=bytearray()
        while not data.endswith(b'\r\n\r\n') and len(data)<16384:
            connection.settimeout(budget()); chunk=connection.recv(1)
            if not chunk: break
            data.extend(chunk)
        if not data.endswith(b'\r\n\r\n'): raise ValueError('Incomplete or oversized HTTP headers')
        line=bytes(data).split(b'\r\n',1)[0]
        match=re.fullmatch(rb'HTTP/1\.[01] ([1-5][0-9]{2})(?:[ \t].*)?',line)
        if not match: raise ValueError('Malformed HTTP status')
        return int(match[1]),bytes(data)
    try:
        budget()
        addresses,error,dns_ms=timeout_dns(host,socket.AF_UNSPEC,min(phase_timeout,budget()),cancel)
        result['timings_ms']['dns']=dns_ms
        budget()
        if error or not addresses:
            result['status']='cancelled' if error.startswith('Cancelled:') else 'proxy_dns_busy' if error.startswith('DNSBusy:') else 'proxy_dns_timeout' if error.startswith('DNSTimeout:') else 'proxy_dns_error'
            result['error_type']=error.split(':',1)[0] if error else 'NoAddress';return result
        info=addresses[0]; address=(info[4][0],port,*info[4][2:])
        phase='tcp';phase_start=time.perf_counter();phase_end=phase_start+phase_timeout
        raw=socket.socket(info[0],socket.SOCK_STREAM,socket.IPPROTO_TCP);raw.settimeout(budget());raw.connect(address)
        result['timings_ms']['tcp']=round((time.perf_counter()-phase_start)*1000,1)
        phase='connect';phase_start=time.perf_counter();phase_end=phase_start+phase_timeout
        raw.settimeout(budget());raw.sendall((f'CONNECT {target}:443 HTTP/1.1\r\nHost: {target}:443\r\nUser-Agent: WinNetDiff/{VERSION}\r\n\r\n').encode('ascii'))
        for _ in range(4):
            status,header=headers(raw)
            if status>=200: break
        result['connect_status']=status;result['timings_ms']['connect']=round((time.perf_counter()-phase_start)*1000,1)
        if status==407:
            result['status']='proxy_auth_required'
            result['auth_schemes']=sorted({match.decode('ascii').lower() for match in re.findall(rb'(?im)^Proxy-Authenticate:\s*(Basic|Digest|NTLM|Negotiate)\b',header)})
            return result
        if not 200<=status<300:
            result['status']='proxy_policy_denied' if status==403 else 'proxy_connect_rejected';return result
        phase='tls';phase_start=time.perf_counter();phase_end=phase_start+phase_timeout
        raw.settimeout(budget());secure=_proxy_tls_context().wrap_socket(raw,server_hostname=target,do_handshake_on_connect=False)
        secure.settimeout(budget());secure.do_handshake();budget()
        result['tls_verified']=True;result['tls_version']=secure.version()
        result['timings_ms']['tls']=round((time.perf_counter()-phase_start)*1000,1)
        phase='http';phase_start=time.perf_counter();phase_end=phase_start+phase_timeout
        secure.settimeout(budget());secure.sendall((f'HEAD / HTTP/1.1\r\nHost: {target}\r\nConnection: close\r\nUser-Agent: WinNetDiff/{VERSION}\r\n\r\n').encode('ascii'))
        status,_=headers(secure);budget();result['http_status']=status;result['status']='proxy_http_observed'
        result['timings_ms']['http']=round((time.perf_counter()-phase_start)*1000,1)
    except _ProxyPathStop as exc: result['status']=str(exc)
    except ssl.SSLCertVerificationError: result['status']='proxy_tls_cert_error'
    except (OSError,ValueError) as exc:
        result['status']='proxy_' + phase + ('_timeout' if isinstance(exc,TimeoutError) else '_error')
        if isinstance(exc,TimeoutError) and time.perf_counter()>=deadline and deadline<=phase_end: result['status']='overall_timeout'
        result['error_type']=type(exc).__name__
    finally:
        if cancel and cancel.is_set(): result['status']='cancelled'
        for connection in (secure,raw):
            if connection is not None:
                try: connection.close()
                except OSError: pass
        result['total_ms']=round((time.perf_counter()-started)*1000,1)
    return result


def diagnose_proxy_paths(proxy: dict, probes: list, target: str, *, confirmed: bool = False, cancel=None) -> dict:
    target = _proxy_target(target)
    plan=proxy_path_plan(proxy,target); tested=[];seen=set()
    direct=[dataclasses.asdict(p) if dataclasses.is_dataclass(p) else p for p in probes]
    direct=[p for p in direct if p.get('host')==target]
    for row in plan['paths']:
        if not confirmed or not row['eligible'] or len(tested)>=2 or cancel and cancel.is_set(): continue
        identity=row['host'],row['port']
        if identity in seen: continue
        seen.add(identity)
        result=probe_proxy_path(target,row,confirmed=True,cancel=cancel);result['source']=row['source'];tested.append(result)
    plan['network_tested']=bool(tested);plan['tests']=tested;plan['cancelled']=bool(cancel and cancel.is_set())
    direct_ok=any(p.get('stage')=='http_ok' for p in direct)
    proxy_ok=any(p.get('status')=='proxy_http_observed' for p in tested)
    plan['direct_stages']=[{'family':p.get('family'),'stage':p.get('stage')} for p in direct]
    plan['comparison']=('both_paths_http_observed' if direct_ok and proxy_ok else 'proxy_only_http_observed' if proxy_ok else
        'authentication_required' if any(p['status']=='proxy_auth_required' for p in tested) else
        'direct_only_http_observed' if direct_ok and any(p['status'] not in ('cancelled','overall_timeout','proxy_dns_busy') for p in tested) else 'not_compared')
    plan['limitations'].append('The proxy resolves the CONNECT target; target IP and route equivalence are unknown. Latencies and E2/E3 are not compared across these paths.')
    return plan


def proxy_path_findings(context: dict) -> list[Finding]:
    if not context: return []
    explanations = {
        'both_paths_http_observed': 'HTTP was observed on both direct and proxy paths; this does not verify every application.',
        'proxy_only_http_observed': 'HTTP was observed through the proxy while direct HTTP was not observed; path differences do not prove a cause.',
        'authentication_required': 'The proxy requires authentication. No credentials were sent; this is not evidence of a dead proxy.',
        'direct_only_http_observed': 'Direct HTTP was observed but the tested proxy path did not complete HTTP; review its separate protocol stages.',
        'not_compared': 'No comparable proxy test was completed. Review static configuration, bypass rules and unresolved PAC.'}
    return [Finding('資訊','代理',msg('Proxy path comparison'),__import__('json').dumps(context,ensure_ascii=False),
        msg('{summary} {scope}', summary=msg(explanations.get(context.get('comparison'),'No comparable proxy test was completed. Review static configuration, bypass rules and unresolved PAC.')),
            scope=msg('Proxy settings and direct socket results describe different paths. Authentication, PAC and application overrides must be interpreted separately.')),
        code='proxy.paths.'+context.get('comparison','not_compared'),risk='read_only')]

