"""Minimized public card: fixed labels/enums/numbers only, no raw report text."""
import math
import re

CARD_TEXT = {
    'en': {'title':'diagnostic card', 'layers':('Proxy','Route','IP','TCP/TLS','Security'),
           'states':('checked','review','incomplete','not tested','cancelled','unknown'),
           'offline':'Probes: not run', 'limits':'Limited evidence; correlation is not causation. Review before sharing.',
           'hypotheses':('Local proxy refused','Virtual route review','IPv6 mismatch','TCP succeeds / TLS fails',
                         'TLS succeeds / HTTP stalls','DNS resolves / TCP fails','Component ownership review',
                         'Security providers review','NDIS ownership review','Fake-IP route suspect')},
    'zh-CN': {'title':'精简诊断卡', 'layers':('代理','路由','IP','TCP/TLS','安全'),
           'states':('已查','待核对','未完成','未测试','已取消','未知'),
           'offline':'探针：未执行', 'limits':'证据有限，相关不代表因果。分享前请审阅。',
           'hypotheses':('本地代理拒绝连接','虚拟路由待核对','IPv6 差异','TCP 成功／TLS 失败',
                         'TLS 成功／HTTP 未返回','DNS 解析／TCP 失败','组件归属待核对',
                         '安全提供者待核对','NDIS 归属待核对','疑似 Fake-IP 残留')},
    'zh-TW': {'title':'精簡診斷卡', 'layers':('代理','路由','IP','TCP/TLS','安全'),
           'states':('已查','待核對','未完成','未測試','已取消','未知'),
           'offline':'探針：未執行', 'limits':'證據有限，相關不代表因果。分享前請審閱。',
           'hypotheses':('本機代理拒絕連線','虛擬路由待核對','IPv6 差異','TCP 成功／TLS 失敗',
                         'TLS 成功／HTTP 未返回','DNS 解析／TCP 失敗','元件歸屬待核對',
                         '安全提供者待核對','NDIS 歸屬待核對','疑似 Fake-IP 殘留')},
}
CARD_SCENARIO_CODES = ('stale_local_proxy','virtual_default_route','ipv6_reachability_mismatch',
    'tcp_ok_tls_failure','tls_ok_http_timeout','dns_ok_connect_unreachable','orphaned_service_or_driver',
    'multiple_security_providers','ndis_binding_corroborated','dns.fake_ip_unroutable_suspected')
CARD_LAYER_KEYS = (('代理','Proxy'),('路由','Route'),('IPv4/IPv6','IPv4/IPv6'),('TCP/TLS','TCP/TLS'),('安全/驅動','Security/drivers'))
CARD_STATUS_GROUPS = (
    {'已稽核','已审核','Audited','Checked'}, {'待核對','待核对','Needs review'},
    {'檢查未完成','检查未完成','Incomplete checks'}, {'未執行主動探針','未执行主动探针','Active probes not run'},
    {'已取消，證據不完整','已取消，证据不完整','Cancelled; incomplete evidence'},
)
CARD_STAGE_ALLOWLIST = frozenset({'http_ok','http_timeout','http_error','http_empty','http_protocol_error',
    'tls_ok','tls_timeout','tls_error','tls_cert_error','tcp_ok','tcp_timeout','tcp_error',
    'dns_error','dns_timeout','overall_timeout','cancelled','probe_error','unrun'})


def _card_field(value, key, default=None):
    return value.get(key, default) if isinstance(value, dict) else getattr(value, key, default)


def _card_time(value):
    if type(value) not in (float, int) or not math.isfinite(value) or not 0 <= value <= 600000:
        return '-'
    return str(round(value))


def compact_share_card(report, locale=None):
    locale = locale or _card_field(report, 'locale', 'en')
    labels = CARD_TEXT.get(locale, CARD_TEXT['en'])
    version = _card_field(report, 'version', VERSION)
    if not isinstance(version, str) or not re.fullmatch(r'\d{1,4}(?:\.\d{1,4}){2,3}(?:[abrc]+\d{1,4})?', version):
        version = VERSION
    lines = ['### WinNetDiff v' + version + ' ' + labels['title']]
    layers = _card_field(report, 'layers', {})
    statuses = []
    for name, keys in zip(labels['layers'], CARD_LAYER_KEYS):
        layer = next((layers[k] for k in keys if k in layers), {})
        raw = _card_field(layer, 'status', '')
        index = next((i for i, values in enumerate(CARD_STATUS_GROUPS) if isinstance(raw, str) and raw in values), 5)
        statuses.append(name + ':' + labels['states'][index])
    lines.append('- ' + '; '.join(statuses))
    footer = ['> ' + labels['limits'], 'WinNetDiff / Alden / MIT']
    candidates = []
    for scenario in list(_card_field(report, 'scenarios', [])) + list(_card_field(report, 'findings', [])):
        code = _card_field(scenario, 'code')
        high = _card_field(scenario, 'priority') in ('high', 0, 1)
        grade = _card_field(scenario, 'grade', _card_field(scenario, 'evidence_grade', 'E1'))
        if code in CARD_SCENARIO_CODES and high and grade in ('E1','E2','E3'):
            text = '- ' + labels['hypotheses'][CARD_SCENARIO_CODES.index(code)] + ' [' + grade + ']'
            if text not in candidates:
                candidates.append(text)
    for hypothesis in candidates[:2]:
        if len('\n'.join(lines+[hypothesis]+footer)) <= 500:
            lines.append(hypothesis)
    probes = _card_field(report, 'probes', [])
    if not probes:
        lines.append('- ' + labels['offline'])
    for probe in probes[:3]:
        family, stage = _card_field(probe, 'family'), _card_field(probe, 'stage')
        family = family if family in ('IPv4','IPv6') else '?'
        stage = stage if isinstance(stage, str) and stage in CARD_STAGE_ALLOWLIST else 'unknown'
        timing = '/'.join(_card_time(_card_field(probe, key)) for key in ('dns_ms','tcp_ms','tls_ms','http_ms'))
        line = '- ' + family + ' D/T/L/H=' + timing + ' ms; ' + stage
        if len('\n'.join(lines+[line]+footer)) <= 500:
            lines.append(line)
    card = '\n'.join(lines+footer)
    # Every variable part is a bounded enum/number/version. Trim complete lines
    # only if a future catalog expansion exceeds the public compact contract.
    while len(card) > 500 and len(lines) > 1:
        lines.pop()
        card = '\n'.join(lines+footer)
    if len(card) > 500:
        raise ValueError('Card catalog exceeds compact character budget')
    return card

# --- core/snapshots.py ---

"""Versioned, local-only network snapshots with deterministic structural diffs.

Snapshots are evidence documents, never executable repair plans. Imported content
is bounded and validated before comparison; an incomplete inventory cannot imply
that an item was removed.
"""

import dataclasses
import datetime as dt
import json
import os
from pathlib import Path
from typing import Any


SNAPSHOT_FORMAT = "winnetdiff.snapshot"
SNAPSHOT_SCHEMA_VERSION = 1
MAX_SNAPSHOT_BYTES = 25 * 1024 * 1024
MAX_CATEGORY_ITEMS = 20000
SNAPSHOT_CATEGORIES = (
    "adapters", "routes", "default_routes", "dns", "proxy", "environment",
    "services", "drivers", "bindings", "security_providers", "installed_apps",
)


class SnapshotError(ValueError):
    """An unsupported, ambiguous, unsafe or malformed snapshot document."""


def _report_data(report: Any) -> dict[str, Any]:
    if dataclasses.is_dataclass(report):
        return dataclasses.asdict(report)
    if isinstance(report, dict):
        return report
    if hasattr(report, "__dict__"):
        return vars(report)
    raise SnapshotError("A report object or mapping is required")


def _canonical(value: Any) -> str:
    try:
        return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    except (ValueError, TypeError) as exc:
        raise SnapshotError("Snapshot values must be finite JSON data") from exc


def _pick(row: dict[str, Any], *keys: str) -> dict[str, Any]:
    return {key: row[key] for key in keys if key in row}


def _stable_id(category: str, identity: Any) -> str:
    # Do not expose raw interface GUIDs, addresses, user aliases or private paths
    # as dictionary keys. Keyed IDs stay comparable on one installation without
    # being reversible by enumerating private address or interface-index spaces.
    return pseudonym_digest("snapshot-row", category + "\0" + _canonical(identity), 24)


def _identity_scheme(snapshot: dict[str, Any]) -> tuple[str, str]:
    # Snapshots written before keyed IDs carry no scheme; they compare only with each other.
    return str(snapshot.get("identity_scheme", "sha256-v0")), str(snapshot.get("identity_key_id", ""))


def _scrub_snapshot(value: Any) -> Any:
    return redacted_data(value)


def _rows(category: str, rows: list[dict[str, Any]], identity, full: bool) -> list[dict[str, Any]]:
    indexed = {}
    for row in rows:
        if not isinstance(row, dict):
            raise SnapshotError(f"{category}: expected object rows")
        ident = _stable_id(category, identity(row))
        clean = row if full else _scrub_snapshot(row)
        if ident in indexed:
            if _canonical(indexed[ident]["value"]) == _canonical(clean):
                continue
            raise SnapshotError(f"{category}: duplicate ambiguous identity {ident}")
        indexed[ident] = {"id": ident, "value": clean}
    return [indexed[key] for key in sorted(indexed)]


def _merge_named_sources(sources: list[tuple[str, list[dict[str, Any]]]]) -> list[dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = {}
    for source, rows in sources:
        for row in rows:
            name = str(row.get("Name") or "").casefold()
            if not name:
                continue
            value = _pick(row, "Name", "DisplayName", "State", "Started", "StartMode", "ServiceType", "PathName", "RegistryStart", "RegistryType")
            grouped.setdefault(name, {"Name": row.get("Name"), "sources": {}})
            previous = grouped[name]["sources"].get(source)
            if previous is not None and _canonical(previous) != _canonical(value):
                raise SnapshotError(f"{source}: duplicate ambiguous service or driver {name}")
            grouped[name]["sources"][source] = value
    return list(grouped.values())


def create_snapshot(report: Any, label: str = "", full: bool = False) -> dict[str, Any]:
    data = _report_data(report)
    route, proxy, security = data.get("route", {}), data.get("proxy", {}), data.get("security", {})
    categories: dict[str, Any] = {}
    categories["adapters"] = _rows("adapters", [
        _pick(row, "Name", "InterfaceDescription", "Status", "ifIndex", "HardwareInterface", "Virtual", "InterfaceGuid", "Classification")
        for row in route.get("adapters", [])],
        lambda r: str(r.get("InterfaceGuid") or r.get("Name") or r.get("ifIndex")).casefold(), full)
    identity_route = lambda r: [r.get("AddressFamily"), r.get("DestinationPrefix"), r.get("InterfaceIndex"),
                                r.get("NextHop", r.get("Gateway")), r.get("PolicyStore")]
    route_keys = ("InterfaceAlias", "InterfaceIndex", "AddressFamily", "DestinationPrefix", "NextHop", "Gateway", "RouteMetric", "InterfaceMetric", "EffectiveMetric", "ConnectionState", "State", "PolicyStore")
    categories["routes"] = _rows("routes", [_pick(r, *route_keys) for r in route.get("routes", [])], identity_route, full)
    categories["default_routes"] = _rows("default_routes", [
        dict(_pick(r, *route_keys), DestinationPrefix=r.get("DestinationPrefix", prefix))
        for key, prefix in (("defaults_ipv4", "0.0.0.0/0"), ("defaults_ipv6", "::/0"))
        for r in route.get(key, [])], identity_route, full)
    dns = route.get("dns_servers", [])
    categories["dns"] = _rows("dns", [_pick(r, "InterfaceIndex", "InterfaceAlias", "AddressFamily", "ServerAddresses") for r in dns],
        lambda r: [r.get("InterfaceIndex", r.get("InterfaceAlias")), r.get("AddressFamily")], full)
    proxy_rows = [{"scope": key, "settings": proxy.get(key, {})} for key in
                  ("wininet", "wininet_user", "wininet_machine", "winhttp", "policy", "policy_user", "effective_scope")]
    # Avoid noisy command transcripts; retain actual settings and direct/proxy state.
    for row in proxy_rows:
        if row["scope"] == "winhttp":
            row["settings"] = _pick(proxy.get("winhttp", {}), "raw", "is_direct", "error", "ok")
    categories["proxy"] = _rows("proxy", proxy_rows, lambda r: r["scope"], full)
    categories["environment"] = _rows("environment", [{"scope": scope, "settings": proxy.get("environ_" + scope, {})}
        for scope in ("user", "machine", "process")], lambda r: r["scope"], full)
    services = _merge_named_sources([("registry", security.get("service_registry", [])), ("wmi", security.get("services_wmi", []))])
    categories["services"] = _rows("services", services, lambda r: str(r["Name"]).casefold(), full)
    drivers = _merge_named_sources([("wmi", security.get("drivers_wmi", [])), ("driverquery", security.get("driverquery", []))])
    categories["drivers"] = _rows("drivers", drivers, lambda r: str(r["Name"]).casefold(), full)
    categories["bindings"] = _rows("bindings", [_pick(r, "Name", "InterfaceDescription", "DisplayName", "ComponentID", "Enabled", "Classification") for r in route.get("bindings", [])],
        lambda r: [str(r.get("Name", "")).casefold(), str(r.get("ComponentID", "")).casefold()], full)
    categories["security_providers"] = _rows("security_providers", [
        _pick(r, "displayName", "pathToSignedProductExe", "pathToSignedReportingExe", "productState")
        for r in security.get("antivirus_products", [])], lambda r: str(r.get("displayName", "")).casefold(), full)
    categories["installed_apps"] = _rows("installed_apps", [
        _pick(r, "DisplayName", "Publisher", "DisplayVersion", "InstallLocation", "Scope", "RegistryKey") for r in security.get("installed_apps", [])],
        lambda r: [r.get("Scope"), r.get("RegistryKey") or [str(r.get("DisplayName", "")).casefold(),
                   str(r.get("Publisher", "")).casefold(), r.get("DisplayVersion"), r.get("InstallLocation")]], full)
    query = route.get("query_status", {})
    complete = security.get("completeness", {})
    route_complete = lambda key: query.get(key) == "ok"
    completeness = {
        "adapters": route_complete("adapters"), "routes": route_complete("routes"),
        "default_routes": route_complete("routes"), "bindings": route_complete("bindings"),
        "dns": route_complete("dns_servers"), "proxy": not bool(proxy.get("errors")) and bool(proxy),
        "environment": not bool(proxy.get("errors")) and bool(proxy),
        "services": bool(complete.get("service_registry")) and bool(complete.get("services_wmi")),
        "drivers": bool(complete.get("drivers_wmi")) and bool(complete.get("driverquery")),
        "security_providers": bool(complete.get("antivirus_products")),
        "installed_apps": bool(complete.get("installed_apps")),
    }
    result = {"format": SNAPSHOT_FORMAT, "schema_version": SNAPSHOT_SCHEMA_VERSION,
              "application_version": str(data.get("version", "unknown")), "locale": str(data.get("locale", "en")),
              "created_at": dt.datetime.now().astimezone().isoformat(timespec="seconds"),
              "observed_at": str(data.get("generated_at", "")), "label": str(label)[:500],
              "privacy": "full" if full else "redacted", "categories": categories,
              "completeness": completeness,
              "identity_scheme": PSEUDONYM_SCHEME, "identity_key_id": pseudonym_key_id(),
              "collection_errors": {"proxy": proxy.get("errors", []), "route": route.get("errors", []), "security": security.get("errors", [])},
              "cancelled": bool(data.get("cancelled", False))}
    if not full:
        result["collection_errors"] = _scrub_snapshot(result["collection_errors"])
        result["label"] = redacted_data(result["label"])
    if result["cancelled"]:
        result["completeness"] = {key: False for key in SNAPSHOT_CATEGORIES}
    _validate_snapshot(result)
    return result


def _validate_tree(value: Any, depth: int = 0) -> None:
    if depth > 40:
        raise SnapshotError("Snapshot nesting exceeds 40 levels")
    if isinstance(value, dict):
        if len(value) > 10000 or any(not isinstance(key, str) or len(key) > 4096 for key in value):
            raise SnapshotError("Invalid or excessive object keys")
        for item in value.values():
            _validate_tree(item, depth + 1)
    elif isinstance(value, list):
        if len(value) > MAX_CATEGORY_ITEMS:
            raise SnapshotError("Snapshot list exceeds item limit")
        for item in value:
            _validate_tree(item, depth + 1)
    elif isinstance(value, str):
        if len(value) > 2 * 1024 * 1024:
            raise SnapshotError("Snapshot text field exceeds limit")
    elif value is not None and not isinstance(value, (int, float, bool)):
        raise SnapshotError("Snapshot contains non-JSON data")


def _validate_snapshot(snapshot: Any) -> dict[str, Any]:
    if not isinstance(snapshot, dict) or snapshot.get("format") != SNAPSHOT_FORMAT:
        raise SnapshotError("Not a WinNetDiff snapshot")
    if type(snapshot.get("schema_version")) is not int or snapshot["schema_version"] != SNAPSHOT_SCHEMA_VERSION:
        raise SnapshotError("Unsupported snapshot schema version")
    if snapshot.get("privacy") not in ("full", "redacted"):
        raise SnapshotError("Snapshot privacy mode is missing or unsupported")
    categories, completeness = snapshot.get("categories"), snapshot.get("completeness")
    if not isinstance(categories, dict) or set(categories) != set(SNAPSHOT_CATEGORIES):
        raise SnapshotError("Snapshot categories do not match schema version 1")
    if not isinstance(completeness, dict) or set(completeness) != set(SNAPSHOT_CATEGORIES) or any(type(v) is not bool for v in completeness.values()):
        raise SnapshotError("Each category needs an explicit completeness boolean")
    if "identity_scheme" in snapshot or "identity_key_id" in snapshot:
        key_id = snapshot.get("identity_key_id")
        if (snapshot.get("identity_scheme") != PSEUDONYM_SCHEME or not isinstance(key_id, str)
                or len(key_id) != 16 or any(c not in "0123456789abcdef" for c in key_id)):
            raise SnapshotError("Unsupported snapshot identity scheme")
    _validate_tree(snapshot)
    _canonical(snapshot)  # Reject NaN/Infinity from permissive JSON decoders.
    for category, rows in categories.items():
        if not isinstance(rows, list) or len(rows) > MAX_CATEGORY_ITEMS:
            raise SnapshotError(f"{category}: expected a bounded entry list")
        seen = set()
        for row in rows:
            if (not isinstance(row, dict) or set(row) != {"id", "value"}
                    or not isinstance(row["id"], str) or len(row["id"]) != 24
                    or any(c not in "0123456789abcdef" for c in row["id"])
                    or not isinstance(row["value"], dict)):
                raise SnapshotError(f"{category}: malformed entry")
            if row["id"] in seen:
                raise SnapshotError(f"{category}: duplicate entry identity")
            seen.add(row["id"])
    return snapshot


def save_snapshot(path: str | Path, report: Any, label: str = "", full: bool = False,
                  overwrite: bool = False) -> dict[str, Any]:
    snapshot = create_snapshot(report, label=label, full=full)
    text = json.dumps(snapshot, ensure_ascii=False, indent=2, allow_nan=False) + "\n"
    atomic_write_text(path, text, overwrite=overwrite)
    return snapshot


def load_snapshot(path: str | Path) -> dict[str, Any]:
    target = Path(path)
    if target.stat().st_size > MAX_SNAPSHOT_BYTES:
        raise SnapshotError("Snapshot file exceeds 25 MiB")
    try:
        with target.open("rb") as stream:
            raw = stream.read(MAX_SNAPSHOT_BYTES + 1)
        if len(raw) > MAX_SNAPSHOT_BYTES:
            raise SnapshotError("Snapshot file exceeds 25 MiB")
        def unique_object(pairs):
            result = {}
            for key, value in pairs:
                if key in result:
                    raise SnapshotError("Duplicate JSON object key")
                result[key] = value
            return result
        snapshot = json.loads(raw.decode("utf-8-sig"), object_pairs_hook=unique_object)
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise SnapshotError("Snapshot is not valid bounded UTF-8 JSON") from exc
    return _validate_snapshot(snapshot)


def _enabled_state(category: str, value: dict[str, Any]) -> Any:
    if category == "bindings" and type(value.get("Enabled")) is bool:
        return value["Enabled"]
    if category == "proxy":
        settings = value.get("settings", {})
        if isinstance(settings, dict):
            if "values" in settings:
                settings = settings.get("values", {})
            if settings.get("ProxyEnable") in (0, 1):
                return bool(settings["ProxyEnable"])
    if category == "services":
        start = value.get("sources", {}).get("registry", {}).get("RegistryStart")
        if type(start) is int:
            return start != 4
    return None


def _changed_fields(before: Any, after: Any, prefix: str = "") -> list[str]:
    if isinstance(before, dict) and isinstance(after, dict):
        result = []
        for key in sorted(set(before) | set(after)):
            path = prefix + "." + key if prefix else key
            if key not in before or key not in after:
                result.append(path)
            else:
                result.extend(_changed_fields(before[key], after[key], path))
        return result
    return [] if _canonical(before) == _canonical(after) else [prefix]


def compare_snapshots(before: dict[str, Any], after: dict[str, Any]) -> dict[str, Any]:
    _validate_snapshot(before)
    _validate_snapshot(after)
    if before["privacy"] != after["privacy"]:
        raise SnapshotError("Compare snapshots with the same privacy mode")
    if _identity_scheme(before) != _identity_scheme(after):
        # Different keys would make every entry look removed and re-added.
        raise SnapshotError("Snapshots use different identity keys; create both on the same installation "
                            "(baselines from earlier versions must be recreated)")
    changes, unavailable = [], []
    for category in SNAPSHOT_CATEGORIES:
        if not before["completeness"][category] or not after["completeness"][category]:
            unavailable.append(category)
            continue
        old = {row["id"]: row["value"] for row in before["categories"][category]}
        new = {row["id"]: row["value"] for row in after["categories"][category]}
        for identity in sorted(set(old) | set(new)):
            a, b = old.get(identity), new.get(identity)
            if a is None:
                kind, fields = "added", []
            elif b is None:
                kind, fields = "removed", []
            else:
                fields = _changed_fields(a, b)
                if not fields:
                    continue
                start, end = _enabled_state(category, a), _enabled_state(category, b)
                kind = ("enabled" if end else "disabled") if start is not None and end is not None and start != end else "changed"
            changes.append({"kind": kind, "category": category, "id": identity,
                            "before": a, "after": b, "changed_fields": fields})
    return {"format": "winnetdiff.snapshot-diff", "schema_version": 1,
            "before_label": before.get("label", ""), "after_label": after.get("label", ""),
            "before_observed_at": before.get("observed_at", ""), "after_observed_at": after.get("observed_at", ""),
            "privacy": before["privacy"], "changes": changes, "unavailable_categories": unavailable,
            "counts": {kind: sum(c["kind"] == kind for c in changes) for kind in ("added", "removed", "enabled", "disabled", "changed")},
            "interpretation": "Changes are observations, not proof of causality. Incomplete inventories are not compared."}

# --- analysis/evidence.py ---

"""One evidence contract shared by findings, scenarios and report assembly.

Grades describe observations, never the probability of a culprit. Repetition
needs a concrete host/family/destination and identical measurement context.
"""

import dataclasses
import ipaddress
import json
from typing import Any

EVIDENCE_GRADES = {
    "E1": "Observed: a directly measured state or one failed attempt; cause is unconfirmed.",
    "E2": "Repeated: the same phase difference repeats across attempts or independent targets.",
    "E3": "Corroborated: repeated differential measurements plus independent relevant configuration evidence; causality remains unproven.",
}


def evidence_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    return dataclasses.asdict(value) if dataclasses.is_dataclass(value) else vars(value)


def probe_attempts(probes: list[Any]) -> list[dict[str, Any]]:
    result = []
    for value in probes:
        probe = evidence_mapping(value)
        for row in probe.get("attempts") or [probe]:
            item = dict(evidence_mapping(row))
            for key in ("host", "family", "context"):
                item.setdefault(key, probe.get(key, {} if key == "context" else ""))
            # Do not fill in a missing attempt IP from the selected best probe:
            # the other attempt may have measured another DNS answer.
            result.append(item)
    return result


def _evidence_path(row: dict[str, Any]) -> tuple[str, str, str, str] | None:
    host, family, address = str(row.get("host") or "").lower(), str(row.get("family") or ""), str(row.get("ip") or "")
    try:
        parsed = ipaddress.ip_address(address)
    except ValueError:
        return None
    if not host or family not in ("IPv4", "IPv6") or parsed.version != (4 if family == "IPv4" else 6):
        return None
    context = row.get("context")
    required_context = {"port", "sni", "method", "path", "connect_timeout", "tls_timeout", "http_timeout"}
    if not isinstance(context, dict) or not required_context <= set(context):
        return None
    return host, family, str(parsed), json.dumps(context, sort_keys=True, ensure_ascii=False, default=str)


def corroborating_orphans(security: dict[str, Any], routes: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Corroborate *observed* orphan candidates without requiring NDIS binding.

    WFP callout drivers and user-mode security services need not be represented
    in Get-NetAdapterBinding. Running state must be independently observable
    from a *completed* runtime inventory. Missing uninstall registration alone
    never proves a component is orphaned or that it caused a TLS failure.
    """
    complete = security.get("completeness") or {}
    if complete.get("installed_apps") is not True or complete.get("service_registry") is not True:
        return []
    # NDIS binding metadata is optional corroboration, not an admission gate:
    # WFP drivers and user-mode security services may have no binding there.
    runtime = [row for key in ("drivers_wmi", "driverquery", "services_wmi")
               if complete.get(key) is True for row in security.get(key, [])]
    registry = security.get("service_registry", [])
    records = security.get("evidence", [])
    # Rebuild from the observations, so a forged/stale serialized graph label
    # cannot invent either a host or an orphan.
    actual_ownership = associate_hosts(security, routes, security.get('wfp_context')) if 'ownership' in security else {}
    host_rows = actual_ownership.get('components', [])
    protected_hosts = {str(row.get('Name') or '').casefold() for row in host_rows
                       if row.get('OwnerApps') or row.get('PossibleHosts')}
    # BdNet/BdSentry are OEM/shared clues. If an independently inventoried
    # potential host is still installed, missing a same-name service entry is
    # not sufficient to treat that shared binary as an orphan.
    related_app_installed = any(
        any(vendor in " ".join(str(app.get(k) or "").casefold()
            for k in ("DisplayName", "Publisher", "InstallLocation"))
            for vendor in ("surfshark", "avira"))
        for app in security.get("installed_apps", [])
    )
    # An independent *correlated* provider/endpoint clue supports a shared OEM
    # component, but a random missing application or arbitrary vendor name does not.
    related_endpoint = any(
        row.get("Status") in ("orphan_candidate", "orphan_security_provider")
        and row.get("Group") in ("Surfshark", "Avira", "SharedEndpoint")
        and not row.get("OwnerApps")
        and (row.get("Running") is True or row.get("Status") == "orphan_security_provider")
        for row in records
    )
    result = []
    for evidence in records:
        name = str(evidence.get("Name") or "").casefold()
        if not name or name in protected_hosts or evidence.get("OwnerApps") or evidence.get("Running") is not True:
            continue
        if evidence.get("Group") == "SharedEndpoint" and related_app_installed:
            continue
        running_peers = [row for row in runtime
                         if str(row.get("Name") or "").casefold() == name
                         and (str(row.get("State") or "").casefold() in
                              ("running", "运行中", "正在运行", "執行中")
                              or row.get("Started") is True)]
        if not running_peers:
            continue
        path = str(evidence.get("Path") or next(
            (row.get("PathName") for row in running_peers if row.get("PathName")), "")).casefold()
        registered = any(
            str(row.get("Name") or "").casefold() == name or
            (path and str(row.get("PathName") or "").casefold() == path)
            for row in registry
        )
        status = evidence.get("Status")
        if status == "registration_missing" and not registered:
            result.append(evidence)
        elif status == "orphan_candidate" and registered:
            # A running file can still be a leftover component. Its existence
            # is not negative evidence. It must also have a complete uninstall
            # inventory and no identified installed owner (checked above).
            result.append(evidence)
        elif (status == "owner_unknown" and evidence.get("Group") == "SharedEndpoint"
              and related_endpoint):
            # Treat as a correlated ownership clue, not a proven WFP filter or
            # a license to uninstall an OEM/shared component automatically.
            result.append(evidence)
    # Re-check generic evidence against raw runtime and complete inventories;
    # a serialized graph label alone cannot supply corroboration.
    accepted = {str(row.get('Name') or '').casefold() for row in result}
    bindings = (routes or {}).get('bindings', [])
    for row in host_rows:
        name = str(row.get('Name') or '').casefold()
        peers = [r for r in runtime if str(r.get('Name') or '').casefold() == name
                 and (r.get('Started') is True or str(r.get('State') or '').casefold() in ('running', '运行中', '正在运行', '執行中'))]
        linked = any(link.get('kind') == 'ndis_service' and link.get('live') is True and link.get('enabled') is True for link in row.get('NetworkLinks', []))
        registered = any(str(r.get('Name') or '').casefold() == name for r in registry)
        inconsistent = ((row.get('Inconsistency') == 'registration_missing' and not registered)
                        or row.get('Inconsistency') == 'running_binary_missing' and row.get('File', {}).get('Exists') is False)
        if (name and name not in accepted and name not in protected_hosts and peers and linked and inconsistent
                and actual_ownership.get('bounded_complete') is True and row.get('EligibleCorroboration') is True):
            result.append(row); accepted.add(name)
    return result


def _comparative_context(host: str, context: dict[str, Any]) -> str:
    value = dict(context)
    # Across independent targets the intended SNI follows each host; all other
    # request parameters and phase budgets must still be identical.
    if str(value.get("sni") or "").casefold() == host.casefold():
        value["sni"] = "<target-host>"
    return json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)


def assess_phase_evidence(probes: list[Any], stages: set[str] | tuple[str, ...], *,
                          corroboration: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    """Assess matching failures without joining IPs, families or timeout causes."""
    attempts = probe_attempts(probes)
    selected = [row for row in attempts if row.get("stage") in stages and
                (not str(row.get("stage", "")).startswith("tls_") or row.get("tcp_ms") is not None)]
    measured_stages = set(stages) - {"overall_timeout", "cancelled", "probe_error", "unrun"}
    paths: dict[tuple[str, str, str, str], list[dict[str, Any]]] = {}
    for row in attempts:
        path = _evidence_path(row)
        if path is not None:
            paths.setdefault(path, []).append(row)
    repeated, persistent = [], []
    concrete_targets: dict[tuple[str, str, str], set[str]] = {}
    for path, rows in paths.items():
        for stage in sorted(measured_stages):
            matching = [r for r in rows if r in selected and r.get("stage") == stage]
            if matching:
                comparison = stage, path[1], _comparative_context(path[0], json.loads(path[3]))
                concrete_targets.setdefault(comparison, set()).add(path[0])
            # Duplicate serialization of one attempt cannot create repetition.
            identities = {r.get("attempt") for r in matching if isinstance(r.get("attempt"), int)}
            if len(identities) >= 2:
                detail = {"host": path[0], "family": path[1], "ip": path[2], "context": json.loads(path[3]), "stage": stage}
                repeated.append(detail)
                if all(r.get("stage") == stage for r in rows):
                    persistent.append(detail)
    persistent_groups: dict[tuple[str, str, str], set[str]] = {}
    for path in persistent:
        comparison = path["stage"], path["family"], _comparative_context(path["host"], path["context"])
        persistent_groups.setdefault(comparison, set()).add(path["host"])
    persistent_multi = any(len(hosts) >= 2 for hosts in persistent_groups.values())
    repeated_measurement = bool(repeated) or any(len(hosts) >= 2 for hosts in concrete_targets.values())
    grade = "E3" if persistent_multi and corroboration else "E2" if repeated_measurement else "E1"
    return {"grade": grade, "attempts": selected, "repeated_paths": repeated,
            "persistent_paths": persistent, "persistent_multitarget": persistent_multi,
            "corroboration": list(corroboration or [])}

# --- collectors/dns_audit.py ---

"""Optional read-only DNS context. Reserved/private addresses alone are not faults."""
import dataclasses
import ipaddress
import threading
from typing import Any

FAKE_IP_NETWORK = ipaddress.ip_network('198.18.0.0/15')
PROXY_CORE_PATTERN = r'(?i)^(clash(?:-meta|-win64)?|mihomo|sing-box|singbox|xray|v2ray)(?:\.exe)?$'


def is_fake_ip(address: str) -> bool:
    try:
        return ipaddress.ip_address(address) in FAKE_IP_NETWORK
    except (ValueError, TypeError):
        return False


def dns_probe_mapping(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else dataclasses.asdict(value)


def select_target_route(address: str, inventory: dict[str, Any]) -> dict[str, Any]:
    """Longest prefix then effective metric, tied to the actual target interface."""
    try:
        target = ipaddress.ip_address(address)
    except ValueError:
        return {'status': 'invalid_address'}
    if inventory.get('query_status', {}).get('routes') != 'ok' or inventory.get('query_status', {}).get('interfaces') != 'ok':
        return {'status': 'unknown', 'reason': 'Route or interface inventory incomplete'}
    candidates, uncertain_prefixes = [], []
    for row in inventory.get('routes', []):
        network = None
        try:
            network = ipaddress.ip_network(str(row.get('DestinationPrefix')), strict=False)
            if target not in network:
                continue
            interfaces = [i for i in inventory.get('interfaces', []) if i.get('InterfaceIndex') == row.get('InterfaceIndex')
                          and str(i.get('AddressFamily')) in (str(2 if target.version == 4 else 23), 'IPv'+str(target.version))]
            interface = interfaces[0] if len(interfaces) == 1 else None
            if not interface:
                uncertain_prefixes.append(network.prefixlen)
                continue
            connection_state = str(interface.get('ConnectionState', '')).lower()
            if connection_state not in ('connected', '1'):
                if connection_state not in ('disconnected', '0'):
                    uncertain_prefixes.append(network.prefixlen)
                continue
            if str(row.get('State', '')).lower() in ('dead', 'invalid', 'unreachable'):
                continue
            metric = int(row.get('RouteMetric', 0)) + int(interface['InterfaceMetric'])
            adapter = next((a for a in inventory.get('adapters', []) if a.get('ifIndex') == row.get('InterfaceIndex')), {})
            if str(adapter.get('Status', '')).lower() in ('down', 'disconnected', 'disabled', 'not present'):
                continue
            candidates.append((network.prefixlen, metric, row, adapter))
        except (ValueError, TypeError, KeyError):
            uncertain_prefixes.append(network.prefixlen if network is not None else 128)
            continue
    if not candidates:
        return {'status': 'unknown' if uncertain_prefixes else 'no_usable_route'}
    candidates.sort(key=lambda item: (-item[0], item[1], str(item[2].get('InterfaceIndex'))))
    best = candidates[0]
    if any(prefix >= best[0] for prefix in uncertain_prefixes):
        return {'status': 'unknown', 'reason': 'A matching route could not be evaluated'}
    tied = [c for c in candidates if c[:2] == best[:2]]
    if len({(c[2].get('InterfaceIndex'), c[2].get('NextHop')) for c in tied}) > 1:
        return {'status': 'ambiguous', 'candidate_count': len(tied)}
    classification = best[3].get('Classification')
    virtual = True if classification == 'virtual' or best[3].get('Virtual') is True else False if classification == 'physical' else None
    return {'status': 'selected', 'route': best[2], 'effective_metric': best[1],
            'adapter': best[3], 'virtual': virtual}


def collect_dns_runtime(routes: dict[str, Any], cancel: threading.Event | None = None) -> dict[str, Any]:
    result: dict[str, Any] = {'cores': [], 'core_query_complete': False, 'listeners': [],
                              'listener_query_complete': False, 'errors': [], 'core_search_scope': 'Known core process names only; renamed or embedded cores can be missed.'}
    if cancel and cancel.is_set():
        return {**result, 'cancelled': True}
    # Names are clues that a core is present; they never prove a healthy mapping.
    core_query = ("ConvertTo-Json -InputObject @(Get-CimInstance Win32_Process | Where-Object {$_.Name -match '" +
                  PROXY_CORE_PATTERN + "'} | Select-Object Name,ProcessId) -Compress")
    cores, error = ps_json(core_query, 5)
    result.update(cores=cores, core_query_complete=not bool(error))
    if error:
        result['errors'].append('proxy_core_inventory: ' + error)
    loopback_configured = any(_dns_loopback(str(server)) for row in routes.get('dns_servers', [])
                              for server in _server_addresses(row.get('ServerAddresses')))
    if loopback_configured and not (cancel and cancel.is_set()):
        # UDP connect success cannot prove a DNS listener. Enumerate endpoints.
        listeners, error = ps_json("ConvertTo-Json -InputObject @(& { Get-NetUDPEndpoint -ErrorAction Stop | Where-Object {$_.LocalPort -eq 53} | Select-Object LocalAddress,LocalPort,OwningProcess; Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object {$_.LocalPort -eq 53} | Select-Object LocalAddress,LocalPort,OwningProcess }) -Compress", 5)
        result.update(listeners=listeners, listener_query_complete=not bool(error))
        if error:
            result['errors'].append('local_dns_listeners: ' + error)
    return result


def _server_addresses(value: Any) -> list[str]:
    """Normalize PowerShell's singleton-or-array DNS server address contract."""
    if isinstance(value, str):
        return [value] if value.strip() else []
    if isinstance(value, (list, tuple)):
        return [address for address in value if isinstance(address, str) and address.strip()]
    return []


def _dns_loopback(value: str) -> bool:
    try:
        return ipaddress.ip_address(value).is_loopback
    except ValueError:
        return False


def audit_dns_state(routes: dict[str, Any], probes: list[Any], runtime: dict[str, Any], *,
                    network_tested: bool) -> dict[str, Any]:
    measured = [dns_probe_mapping(p) for p in probes]
    result: dict[str, Any] = {'enabled': True, 'network_tested': network_tested, 'targets': [], 'dns_servers': [],
        'runtime': runtime, 'limitations': ['System resolver results are correlated with configured DNS servers; the actual server answering each query was not captured.',
        '198.18.0.0/15 is a benchmarking range and a Fake-IP clue, not proof of DNS hijacking.']}
    for row in routes.get('dns_servers', []):
        for address in _server_addresses(row.get('ServerAddresses')):
            try:
                parsed = ipaddress.ip_address(address)
            except ValueError:
                continue
            status = 'configured_only'
            if parsed.is_loopback:
                listeners = [r for r in runtime.get('listeners', []) if r.get('LocalAddress') in (address, '0.0.0.0' if parsed.version == 4 else '::')]
                status = 'local_listener_present' if listeners else 'local_listener_missing' if runtime.get('listener_query_complete') else 'local_listener_unknown'
            elif parsed.is_private:
                status = 'private_dns_configured'
            adapter = next((a for a in routes.get('adapters', []) if a.get('ifIndex') == row.get('InterfaceIndex')), {})
            interface_states = [i for i in routes.get('interfaces', []) if i.get('InterfaceIndex') == row.get('InterfaceIndex') and str(i.get('AddressFamily')) in (str(2 if parsed.version == 4 else 23), 'IPv'+str(parsed.version))]
            active = any(str(i.get('ConnectionState', '')).lower() in ('connected', '1') for i in interface_states) if interface_states else None
            result['dns_servers'].append({'address': address, 'active_interface': active,
                'adapter_state': adapter.get('Status'), 'virtual': adapter.get('Classification') == 'virtual' if adapter else None, 'interface_index': row.get('InterfaceIndex'),
                'interface_alias': row.get('InterfaceAlias'), 'status': status,
                'address_kind': 'loopback' if parsed.is_loopback else 'benchmarking' if is_fake_ip(address) else 'private' if parsed.is_private else 'public',
                'resolution_observed': any(p.get('resolved_addresses') or p.get('ip') for p in measured),
                'note': 'A configured private/local DNS address alone does not establish a fault.'})
    seen = set()
    for probe in measured:
        addresses = probe.get('resolved_addresses') or [probe.get('ip')]
        for address in addresses:
            if not is_fake_ip(address) or (probe.get('host'), address) in seen:
                continue
            seen.add((probe.get('host'), address))
            route = select_target_route(address, routes)
            attempts = probe.get('attempts') or [probe]
            matching = [a for a in attempts if a.get('ip') == address]
            success = any(str(a.get('stage', '')).startswith('http_') or a.get('stage') == 'tls_ok' for a in matching)
            failed = bool(matching) and all(a.get('stage') in ('tcp_timeout', 'tcp_error') for a in matching)
            core_present = bool(runtime.get('cores'))
            core_absent = runtime.get('core_query_complete') is True and not core_present
            status = 'fake_ip_indeterminate'
            if network_tested and success and (core_present or route.get('virtual')):
                status = 'expected_fake_ip_active_proxy'
            elif network_tested and failed and core_absent and route.get('status') == 'no_usable_route':
                status = 'fake_ip_unroutable_suspected'
            result['targets'].append({'host': probe.get('host'), 'address': address, 'status': status,
                'route_context': route, 'core_present': core_present, 'known_core_absence_observed': core_absent,
                'matching_attempts': matching, 'dns_source': 'system_getaddrinfo',
                'configured_dns': [d for d in result['dns_servers'] if (
                    d['interface_index'] == route['route'].get('InterfaceIndex')
                    if isinstance(route.get('route'), dict) else
                    route.get('status') == 'no_usable_route' and d.get('active_interface') is True)]})
    return result

