"""Conservative Fake-IP findings; no address-only automatic repair."""
import json


def fake_ip_findings(audit):
    findings = []
    for target in audit.get('targets', []):
        status = target['status']
        suspect = status == 'fake_ip_unroutable_suspected'
        title = {'expected_fake_ip_active_proxy': 'Fake-IP mapping works with an active proxy path',
                 'fake_ip_unroutable_suspected': 'Suspected stale Fake-IP mapping without a usable target route',
                 'fake_ip_indeterminate': 'Fake-IP clue needs additional verification'}[status]
        findings.append(Finding('高優先級' if suspect else '資訊', '路由', title,
            json.dumps(target, ensure_ascii=False),
            'The system resolved a benchmarking-range address. Review the recorded target route, core inventory and matching TCP results; no DNS hijacking or culprit is proven.',
            confidence='中' if suspect else '低', priority=1 if suspect else 3,
            code='dns.' + status, evidence_grade=assess_phase_evidence(target.get('matching_attempts', []), {'tcp_timeout', 'tcp_error'})['grade'] if suspect else 'E1',
            alternatives=['Intentional TUN/transparent proxy mapping, incomplete inventory, policy routing or a lab network.'],
            verification=['Verify the owning proxy and target-specific route before changing any DNS setting.']))
    for server in audit.get('dns_servers', []):
        if server['status'] == 'local_listener_missing' and server.get('active_interface') is True:
            findings.append(Finding('資訊', '路由', 'Configured loopback DNS has no observed port 53 listener',
                json.dumps(server, ensure_ascii=False),
                'The endpoint inventory found no matching listener. Resolver caching, interception or another configured DNS server may still work; verify an actual query before changing configuration.',
                confidence='低', code='dns.local_listener_missing'))
    return findings

# --- probes/pmtu.py ---

"""Opt-in, bounded IPv4 DF Echo evidence; never diagnoses a PMTUD black hole."""
import datetime as dt
import ipaddress
import math
import re
import threading
import time
from typing import Any

PMTU_LIMITATION = 'ICMP Echo may be filtered and may follow a different policy from TLS. Fragmentation Needed means feedback arrived; neither silence nor size differences prove a PMTUD black hole. No MTU, MSS or registry setting was changed.'
PMTU_STATUS_TEXT = {
    'mtu_limited_feedback_present': 'A tested size exceeded the path limit; ICMP feedback arrived.',
    'size_or_icmp_inconclusive': 'Size-dependent silence or ICMP filtering; MTU cause unconfirmed.',
    'icmp_no_result': 'No ICMP result; the target may filter Echo.',
    'tested_sizes_replied': 'All tested payload sizes received Echo replies.',
    'unreachable': 'The local host or route reported unreachable.',
    'permission_denied': 'The probe was denied permission.',
    'cancelled': 'The auxiliary probe was cancelled.',
    'overall_timeout': 'The auxiliary probe exhausted its time budget.',
    'inconclusive': 'Auxiliary evidence is inconclusive.',
}


def pmtu_summary(result, locale='en'):
    lines = [tr(PMTU_STATUS_TEXT.get(result.get('status'), 'Auxiliary evidence is inconclusive.'), locale)]
    for sample in result.get('samples', []):
        lines.append(tr('ICMP payload {payload} B; estimated IPv4 packet {packet} B: {status}', locale,
                        payload=sample['payload_bytes'], packet=sample['estimated_ipv4_packet_bytes'], status=sample['status']))
    lines.append(tr(PMTU_LIMITATION, locale))
    return '\n'.join(lines)


def parse_ping_result(result: dict[str, Any]) -> str:
    text = str(result.get('stdout', '')) + '\n' + str(result.get('stderr', ''))
    if re.search(r'(?i)needs? to be fragment|fragmentation needed|需要(?:拆分|分片|分段)|必須(?:分割|分段)|需要分割|需(?:要)?片段', text):
        return 'fragmentation_needed'
    if re.search(r'(?i)access (?:is )?denied|permission denied|requires elevation|拒[絕绝](?:存取|访问)|權限不足|权限不足', text):
        return 'permission_denied'
    if re.search(r'(?i)unreachable|general failure|transmit failed|無法連線|无法访问|无法传输|一般故障|常見失敗|一般失敗|目的地主機無法連線|网络不可达', text):
        return 'unreachable'
    # TTL is present in actual IPv4 Echo replies, including Chinese Windows.
    # The process exit code alone cannot establish an Echo reply.
    if re.search(r'(?i)\bTTL\s*[=:]\s*\d+', text):
        return 'echo_reply'
    if result.get('timed_out') or re.search(r'(?i)timed? out|request timeout|請求等候逾時|要求等候逾時|请求超时|要求逾時', text):
        return 'icmp_timeout'
    if result.get('returncode') is None:
        return 'execution_error'
    return 'unrecognized'


def classify_pmtu(samples: list[dict[str, Any]]) -> str:
    if not samples:
        return 'not_tested'
    statuses = {s['status'] for s in samples}
    if 'permission_denied' in statuses:
        return 'permission_denied'
    if 'fragmentation_needed' in statuses:
        return 'mtu_limited_feedback_present'
    replies = [s['payload_bytes'] for s in samples if s['status'] == 'echo_reply']
    timeouts = [s['payload_bytes'] for s in samples if s['status'] == 'icmp_timeout']
    if replies and timeouts and max(timeouts) > min(replies):
        return 'size_or_icmp_inconclusive'
    if statuses == {'echo_reply'}:
        return 'tested_sizes_replied'
    if statuses <= {'icmp_timeout'}:
        return 'icmp_no_result'
    if 'unreachable' in statuses:
        return 'unreachable'
    return 'inconclusive'


def pmtu_candidates(probes: list[Any]) -> list[str]:
    evidence = assess_phase_evidence(probes, {'tls_timeout'})
    candidates = []
    for path in evidence['persistent_paths']:
        address = path['ip']
        if path['family'] == 'IPv4' and not is_fake_ip(address) and address not in candidates:
            candidates.append(address)
    return candidates[:2]


def probe_pmtu(address: str, *, confirmed: bool = False, payload_sizes=(1200, 1472), retries=1,
               timeout_ms=800, overall_timeout=4.0, cancel: threading.Event | None = None) -> dict[str, Any]:
    result: dict[str, Any] = {'address': address, 'tested': False, 'status': 'not_tested', 'samples': [],
                              'limitation': PMTU_LIMITATION, 'blackhole_confirmed': False, 'measured_at': dt.datetime.now().astimezone().isoformat(timespec='seconds')}
    if confirmed is not True:
        return {**result, 'status': 'consent_required'}
    try:
        target = ipaddress.ip_address(address)
    except ValueError:
        return {**result, 'status': 'invalid_address'}
    if target.version != 4:
        return {**result, 'status': 'ipv6_not_supported'}
    if target.is_multicast or target.is_unspecified or is_fake_ip(address):
        return {**result, 'status': 'unsuitable_target'}
    if (type(retries) is not int or not 1 <= retries <= 2 or type(timeout_ms) is not int or not 100 <= timeout_ms <= 2000 or
            not isinstance(overall_timeout, (int, float)) or isinstance(overall_timeout, bool) or not math.isfinite(overall_timeout) or not 0.1 <= overall_timeout <= 10):
        raise ValueError('Invalid PMTU time/retry budget')
    sizes = tuple(payload_sizes)
    if not 1 <= len(sizes) <= 4 or any(type(s) is not int or not 32 <= s <= 65000 for s in sizes):
        raise ValueError('Invalid PMTU ICMP payload sizes')
    started = time.perf_counter()
    deadline = started + overall_timeout
    stopped = ''
    for size in sorted(set(sizes)):
        for index in range(retries):
            if cancel and cancel.is_set():
                stopped = 'cancelled'; break
            remaining = deadline - time.perf_counter()
            if remaining <= 0.05:
                stopped = 'overall_timeout'; break
            wait_ms = min(timeout_ms, max(1, int(remaining * 1000)))
            command = ['ping.exe', '-4', '-f', '-l', str(size), '-n', '1', '-w', str(wait_ms), str(target)]
            # Each command is bounded too. Cancellation is checked between
            # commands, at most one <=2.4-second ping wait from this boundary.
            response = run_command(command, timeout=min(remaining, wait_ms / 1000 + 0.4))
            result['samples'].append({'payload_bytes': size, 'estimated_ipv4_packet_bytes': size + 28,
                'attempt': index + 1, 'status': parse_ping_result(response), 'command': command,
                'response': response})
            if cancel and cancel.is_set():
                stopped = 'cancelled'; break
            if time.perf_counter() >= deadline:
                stopped = 'overall_timeout'; break
        if stopped:
            break
    result.update(tested=bool(result['samples']), status=stopped or classify_pmtu(result['samples']),
                  elapsed_ms=round((time.perf_counter()-started)*1000, 1), configured_overall_seconds=overall_timeout)
    if cancel and cancel.is_set():
        result['status'] = 'cancelled'
    return result

# --- analysis/scenarios.py ---

"""Explainable scenario hypotheses built from observed evidence, not vendor names.

Evidence grades describe support, not calibrated probabilities. No rule proves a
kernel deadlock or authorizes a system mutation.
"""

import dataclasses
import re
from typing import Any


def _scenario_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    if dataclasses.is_dataclass(value):
        return dataclasses.asdict(value)
    return vars(value) if hasattr(value, "__dict__") else {}


def _scenario_row(code, title, layer, evidence, reasoning, alternatives, verification,
                  conditions, risk="read_only", grade="E1", priority="review"):
    return {"code": code, "title": title, "layer": layer, "evidence": evidence,
            "reasoning": reasoning, "alternatives": alternatives, "verification": verification,
            "conditions": conditions, "risk": risk, "grade": grade,
            "grade_definition": EVIDENCE_GRADES[grade], "priority": priority,
            "repair": "No automatic system change is authorized by this hypothesis."}


def evaluate_scenarios(report: Any, baseline_diff: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    data = _scenario_mapping(report)
    route, proxy, security = data.get("route", {}), data.get("proxy", {}), data.get("security", {})
    probes = [_scenario_mapping(p) for p in data.get("probes", [])]
    attempts = probe_attempts(probes)
    results = []
    for listener in proxy.get("local_listeners", []):
        active = [r for r in listener.get("references", []) if r.get("active") is True]
        if active and listener.get("confirmed_dead") and not listener.get("accepts_tcp"):
            results.append(_scenario_row("stale_local_proxy", "Enabled proxy points to a refused local port", "proxy", [listener],
                "A configured, active proxy endpoint repeatedly refused TCP connections. Applications using that proxy cannot reach it.",
                ["The proxy is temporarily restarting.", "A local firewall may reject the connection."],
                ["Start the expected proxy client and retry the same endpoint.", "If the client is no longer used, preview the scoped user-proxy repair and verify the same targets afterward."],
                ["The proxy source is actually enabled, not merely an unused environment variable.", "No listener ownership evidence contradicts the refusal."],
                risk="low_with_confirmation", priority="high"))
    connected = [r for r in route.get("defaults_ipv4", []) if str(r.get("ConnectionState", "Connected")) in ("Connected", "1") and r.get("EffectiveMetric") is not None]
    if len(connected) > 1:
        ranked = sorted(connected, key=lambda r: r["EffectiveMetric"])
        first = ranked[0]
        adapter = next((a for a in route.get("adapters", []) if a.get("ifIndex") == first.get("InterfaceIndex")), {})
        if adapter.get("Classification") == "virtual" or re.search(r"vpn|wintun|wireguard|vethernet|virtualbox|docker", str(first.get("InterfaceAlias", "")), re.I):
            results.append(_scenario_row("virtual_default_route", "A virtual interface has the lowest default-route metric", "route", ranked,
                "For equal destination-prefix lengths, route and interface metrics prefer this virtual interface.",
                ["An active VPN intentionally owns the default route.", "More specific split-tunnel routes may take precedence."],
                ["Compare with a known-good snapshot and the intended VPN state.", "Inspect the route for the affected target IP before changing any interface."],
                ["Multiple connected default routes were successfully enumerated.", "Metrics refer to the same address family and prefix length."], risk="manual_network_change"))
    v4good = {p.get("host") for p in probes if p.get("family") == "IPv4" and p.get("stage") == "http_ok"}
    v6bad = [p for p in probes if p.get("family") == "IPv6" and p.get("host") in v4good and p.get("stage") != "http_ok"]
    bindings = route.get("ipv6_bindings", [])
    v6_enabled = any(b.get("Enabled") is True for b in bindings)
    query_ok = route.get("query_status", {}).get("routes") == "ok" and route.get("query_status", {}).get("bindings") == "ok"
    if v6bad and query_ok and v6_enabled and route.get("defaults_ipv6"):
        results.append(_scenario_row("ipv6_reachability_mismatch", "IPv6 is configured but differs from the same-host IPv4 result", "ipv4_ipv6", v6bad,
            "The same host works over IPv4 while an enabled, routed IPv6 path fails at the recorded phase.",
            ["The host has no usable AAAA record.", "An upstream IPv6 route, MTU, server or intermediate device differs."],
            ["Repeat the same domain over both families and inspect the exact IPv6 target route.", "Compare router advertisements and known-good local IPv6 configuration."],
            ["IPv4 succeeded for the same host.", "IPv6 binding and routing queries completed; lack of IPv6 service alone is not a system fault."], risk="read_only"))
    orphan_corroboration = corroborating_orphans(security, route)
    tls_assessment = assess_phase_evidence(probes, {"tls_timeout", "tls_error", "tls_cert_error"}, corroboration=orphan_corroboration)
    tls_failures = tls_assessment["attempts"]
    orphan = [e for e in security.get("evidence", []) if e.get("Status") in ("orphan_candidate", "registration_missing", "orphan_security_provider")]
    if tls_failures:
        grade = tls_assessment["grade"]
        results.append(_scenario_row("tcp_ok_tls_failure", "TCP established but TLS did not complete normally", "tcp_tls",
            tls_assessment,
            "Each recorded attempt completed TCP on the same socket before its TLS-stage failure. Relevant orphan evidence increases investigation priority when the differential repeats.",
            ["Path MTU or packet loss.", "Server-side policy or failure.", "TLS inspection or other intermediate equipment.", "Certificate/time/trust-store failure when certificate validation is the measured error."],
            ["Repeat identical targets and parameters; preserve all IPs and attempt outcomes.", "Inspect read-only WFP/NDIS ownership evidence and compare before/after snapshots.", "Use a trusted vendor removal procedure only after verifying product identity and suitability."],
            ["tcp_ms is present for each TLS-stage failure.", "E3 requires repeated multi-target failures and independently enumerated relevant orphan candidates.", "Correlation does not establish a kernel deadlock or identify a culpable driver."],
            risk="manual_security_component_review", grade=grade, priority="high" if grade == "E3" else "review"))
    http_timeouts = [p for p in attempts if p.get("stage") == "http_timeout" and p.get("tls_ms") is not None]
    if http_timeouts:
        results.append(_scenario_row("tls_ok_http_timeout", "TLS completed but HTTP response did not arrive in time", "http", http_timeouts,
            "The failure is after verified TLS completion, so it is distinct from a TLS handshake failure.",
            ["Server-side application delay.", "Application/content filtering.", "HTTP request policy or connection loss."],
            ["Repeat the same host, method and timeout; compare an independent target.", "Inspect the HTTP-stage error and latency distribution."],
            ["A TLS duration is recorded before HTTP timeout."], grade=assess_phase_evidence(probes, {"http_timeout"})["grade"]))
    unreachable = [p for p in attempts if p.get("stage") in ("tcp_timeout", "tcp_error") and p.get("ip") and p.get("dns_ms") is not None]
    if unreachable:
        results.append(_scenario_row("dns_ok_connect_unreachable", "DNS returned an address but TCP was unreachable", "dns_tcp", unreachable,
            "DNS resolution and TCP reachability are independent stages; the measured destination was known before connect failed.",
            ["Incorrect or stale DNS response.", "Route, firewall, destination policy or ordinary packet loss.", "No usable route for the selected address family."],
            ["Inspect the exact target-IP route and compare another address returned for the same host.", "Repeat across targets and separate IPv4 from IPv6."],
            ["The attempt records an IP and a completed DNS measurement."], grade=assess_phase_evidence(probes, {"tcp_timeout", "tcp_error"})["grade"]))
    if orphan:
        results.append(_scenario_row("orphaned_service_or_driver", "Security or VPN component ownership needs review", "security_driver", orphan,
            "Independent inventory records show an ownership/registration inconsistency. Missing uninstall registration alone is not proof that the main program was removed.",
            ["Portable or enterprise-deployed software.", "A shared SDK owned by a different installed product.", "A component pending reboot or a stale security-center registration."],
            ["Verify publisher signature, product metadata, service path and the current antivirus provider.", "Compare the component with the installed-app list and a known-good snapshot."],
            ["The inventory completeness attached to the evidence supports the stated absence.", "Names alone do not establish product ownership, malware or fault."], risk="manual_security_component_review"))
    products = security.get("antivirus_products", [])
    if len(products) >= 2 and security.get("completeness", {}).get("antivirus_products") is True:
        results.append(_scenario_row("multiple_security_providers", "Multiple antivirus products are registered", "security_driver", products,
            "Security Center contains more than one provider record. Registration does not establish that each product actively filters traffic.",
            ["A stale provider record.", "Expected coexistence with passive or managed products."],
            ["Check the active protection status in the supported Windows/vendor interface.", "Verify signatures and ownership before changing any product."],
            ["The Security Center inventory completed successfully."], risk="manual_security_component_review"))
    suspicious_bindings = [b for b in route.get("bindings", []) if b.get("Enabled") is True
                           and b.get("Classification") not in ("windows", "known-third-party")
                           and any(e.get("Status") in ("orphan_candidate", "registration_missing")
                                   for e in b.get("OwnerEvidence", {}).get("SecurityCorrelation", []))]
    if suspicious_bindings:
        results.append(_scenario_row("ndis_binding_corroborated", "An enabled binding has relevant ownership concerns", "ndis", suspicious_bindings,
            "The enabled binding is correlated with independent service/driver ownership evidence, rather than being flagged solely because its ID is non-Microsoft.",
            ["A legitimate shared filter remains needed by active software.", "The filter is present but unrelated to the current failure."],
            ["Record one exact adapter/component state and prepare its inverse operation.", "Review vendor ownership; only then consider a confirmed one-item isolation test and compare identical probes."],
            ["The binding is currently enabled.", "The correlated record indicates an orphan or registration concern, not just an installed owner."], risk="manual_network_change"))
    if baseline_diff and baseline_diff.get("changes"):
        changes = baseline_diff["changes"]
        results.append(_scenario_row("configuration_changed_since_baseline", "Network configuration differs from the selected baseline", "snapshot", changes,
            "The selected snapshots contain structural additions, removals or configuration changes. Timing alone does not identify the cause.",
            ["A deliberate VPN/network change.", "Application installation or removal.", "Windows servicing or adapter renumbering."],
            ["Correlate the snapshot times with a user-confirmed change or Windows update event.", "Check the changed component and repeat consistent target probes."],
            ["Snapshot schemas and privacy modes are compatible.", "Only complete inventories are compared; Windows-update causation is never inferred from changes alone."], risk="read_only"))
    return results

# --- analysis/verification.py ---

"""Same-configuration repair verification without conflating execution and efficacy."""

import dataclasses
from typing import Any



def _verification_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    return dataclasses.asdict(value) if dataclasses.is_dataclass(value) else vars(value)


def _verification_probe_score(stage: str) -> int:
    # Certificate/protocol/timeout differences within a stage are not ranked as
    # improvement; only demonstrable progress through the protocol stack counts.
    if stage == "http_ok":
        return 4
    if stage in ("http_timeout", "http_error", "http_empty", "http_protocol_error", "tls_ok"):
        return 3
    if stage in ("tls_timeout", "tls_error", "tls_cert_error", "tcp_ok"):
        return 2
    if stage in ("tcp_timeout", "tcp_error"):
        return 1
    return 0


def _verification_attempts(probe: dict[str, Any]) -> list[dict[str, Any]]:
    return [_verification_mapping(item) for item in (probe.get("attempts") or [probe])]


def compare_verification(before_report: Any, after_report: Any) -> dict[str, Any]:
    before, after = _verification_mapping(before_report), _verification_mapping(after_report)
    result: dict[str, Any] = {"status": "incomparable", "effective": False,
        "interpretation": "Repair execution and observed network improvement are separate outcomes.",
        "reasons": [], "probe_changes": [], "configuration_diff": None}
    if sorted(before.get("hosts", [])) != sorted(after.get("hosts", [])):
        result["reasons"].append("Target domains differ; rerun the same targets.")
    if before.get("scan_options", {}) != after.get("scan_options", {}):
        result["reasons"].append("Diagnostic parameters differ; rerun identical options.")
    elif not before.get("scan_options"):
        result["reasons"].append("Recorded diagnostic parameters are missing; equal defaults cannot be assumed.")
    if before.get("cancelled") or after.get("cancelled"):
        result["reasons"].append("A scan was cancelled; evidence is incomplete.")
    if any(a.get("stage") == "overall_timeout" for report in (before, after)
           for p in report.get("probes", []) for a in _verification_attempts(_verification_mapping(p))):
        result["reasons"].append("An overall measurement deadline expired; protocol progress cannot be compared reliably.")
    if result["reasons"]:
        return result
    old_probes = {_verification_probe_identity(p): _verification_mapping(p) for p in before.get("probes", [])}
    new_probes = {_verification_probe_identity(p): _verification_mapping(p) for p in after.get("probes", [])}
    if len(old_probes) != len(before.get("probes", [])) or len(new_probes) != len(after.get("probes", [])):
        result["reasons"].append("Duplicate host/family probe identities make verification ambiguous.")
        return result
    if not old_probes or set(old_probes) != set(new_probes):
        result["reasons"].append("Matching active-probe observations are missing; configuration changes alone do not verify network improvement.")
        return result
    improved, regressed, address_differences = [], [], []
    for identity in sorted(old_probes):
        old, new = old_probes[identity], new_probes[identity]
        before_attempts, after_attempts = _verification_attempts(old), _verification_attempts(new)
        old_scores = [_verification_probe_score(p.get("stage", "")) for p in before_attempts]
        new_scores = [_verification_probe_score(p.get("stage", "")) for p in after_attempts]
        old_rate = sum(p.get("stage") == "http_ok" for p in before_attempts) / len(before_attempts)
        new_rate = sum(p.get("stage") == "http_ok" for p in after_attempts) / len(after_attempts)
        phase_progress = min(new_scores) > min(old_scores) and max(new_scores) >= max(old_scores)
        phase_regression = min(new_scores) < min(old_scores) or max(new_scores) < max(old_scores)
        change = {"host": identity[0], "family": identity[1],
                  "before_stage": old.get("stage"), "after_stage": new.get("stage"),
                  "before_success_rate": old_rate, "after_success_rate": new_rate,
                  "before_attempt_count": len(before_attempts), "after_attempt_count": len(after_attempts),
                  "before_ip": old.get("ip"), "after_ip": new.get("ip"),
                  "durations_ms": {phase: {"before": old.get(phase + "_ms"), "after": new.get(phase + "_ms")}
                                   for phase in ("dns", "tcp", "tls", "http")}}
        if old_rate < new_rate or phase_progress:
            improved.append(identity)
            change["result"] = "observed_improvement"
        elif new_rate < old_rate or phase_regression:
            regressed.append(identity)
            change["result"] = "observed_regression"
        else:
            change["result"] = "not_verified"
        old_addresses = {p.get("ip") for p in before_attempts if p.get("ip")}
        new_addresses = {p.get("ip") for p in after_attempts if p.get("ip")}
        if old_addresses != new_addresses:
            address_differences.append(identity)
        result["probe_changes"].append(change)
    try:
        result["configuration_diff"] = compare_snapshots(create_snapshot(before), create_snapshot(after))
    except SnapshotError as exc:
        result["configuration_diff_error"] = str(exc)
    if regressed:
        result["status"] = "regressed"
        result["reasons"].append("At least one same-target protocol path regressed; do not claim repair success.")
    elif improved:
        result["status"], result["effective"] = "improved", True
        result["reasons"].append("The same target/options made demonstrable protocol progress or a higher HTTP-response rate; this does not prove causation.")
    else:
        result["status"] = "not_verified"
        result["reasons"].append("No protocol progress or higher HTTP-response rate was demonstrated. A faster single duration does not establish efficacy.")
    if address_differences:
        result["reasons"].append("Resolved IP sets changed for some targets; server/address variation is an alternative explanation.")
    return result


def _verification_probe_identity(value: Any) -> tuple[str, str]:
    row = _verification_mapping(value)
    return str(row.get("host", "")), str(row.get("family", ""))

